// Левит — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["І воззвав Господь до Мойсея і сказав йому зі скинії зібрання, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли хто з вас хоче принести жертву Господу, то, якщо з худоби, приносьте жертву вашу з худоби великої і дрібної.","Якщо жертва його є всепаленням з великої худоби, нехай принесе її чоловічої статі, без вад; нехай приведе її до дверей скинії зібрання, щоб придбати йому благовоління перед Господом;","і покладе руку свою на голову жертви всепалення — і придбає він благовоління, в очищення гріхів його;","і заколе тельця перед Господом; сини ж Ааронові, священики, принесуть кров і покроплять кров’ю з усіх боків на жертовник, який при вході у скинію зібрання;","і зніме шкуру з жертви всепалення і розсіче її на частини;","сини ж Ааронові, священики, покладуть на жертовник вогонь і на вогні розкладуть дрова;","і розкладуть сини Ааронові, священики, частини, голову і жир на дровах, що на вогні, на жертовнику;","а нутрощі жертви і ноги її вимиє він водою, і спалить священик усе на жертовнику: це всепалення, жертва, пахощі, приємні Господу.","Якщо жертва всепалення його [Господу] з дрібної худоби, з овець, або з кіз, нехай принесе її чоловічої статі, без вад, [і нехай покладе руку на голову її,]","і заколе її перед Господом на північній стороні жертовника, і сини Ааронові, священики, покроплять кров’ю її на жертовник з усіх боків;","і розсічуть її на частини, відокремивши голову її і жир її, і розкладе їх священик на дровах, які на вогні, на жертовнику,","а нутрощі і ноги вимиє водою, і принесе священик усе і спалить на жертовнику: це всепалення, жертва, пахощі, приємні Господу.","Якщо ж із птахів приносить він Господу всепалення, нехай принесе жертву свою з горлиць, або з молодих голубів;","священик принесе її до жертовника, і скрутить їй голову, і спалить на жертовнику, а кров вицідить до стіни жертовника;","зоб її з пір’ям її відніме і кине його поряд з жертовником на східну сторону, де попіл;","і надламає її в крилах її, не відокремлюючи їх, і спалить її священик на жертовнику, на дровах, які на вогні: це всепалення, жертва, пахощі, приємні Господу."],"x":{"1":"2.12.8","3":"1.29.10","4":"1.29.10|62.3.25|64.5.19","6":"2.7.8","7":"2.9.24","9":"0.8.21|1.29.25|66.5.2","14":"2.5.7","16":"2.4.12|2.6.10"}},{"v":["Якщо яка душа хоче принести Господу жертву приношення хлібного, нехай принесе пшеничного борошна, й увіллє на нього єлею, і покладе на нього ливану,","і принесе його до синів Ааронових, священиків, і візьме повну жменю борошна з єлеєм і з усім ливаном, і спалить це священик у пам’ять на жертовнику; це жертва, пахощі, приємні Господу;","а залишки від приношення хлібного Аарону і синам його: це велика святиня з жертв Господніх.","Якщо ж приносиш жертву приношення хлібного зі спеченого в печі, то принось пшеничні хліби прісні, змішані з єлеєм, і коржі прісні, помазані єлеєм.","Якщо жертва твоя — приношення хлібне зі сковороди, то це повинно бути пшеничне борошно, змішане з єлеєм, прісне;","розламай його на шматки й влий на нього єлею: це приношення хлібне [Господеві].","Якщо жертва твоя — приношення хлібне з горщика, то потрібно зробити це із пшеничного борошна з єлеєм,","і принеси приношення, що з цього складено, Господу; представ це священику, а він принесе його до жертовника;","і візьме священик із цієї жертви частину в пам’ять і спалить на жертовнику: це жертва, пахощі, приємні Господеві;","а залишки приношення хлібного Аарону і синам його: це велика святиня з жертв Господніх.","Ніякого приношення хлібного, яке приносите Господу, не робіть квасного, тому що ні квасного, ні меду не повинні ви спалювати в жертву Господу;","як приношення початків приносьте їх Господеві, а на жертовник не можна возносити їх у приємні пахощі.","Всяке приношення твоє хлібне соли́ сіллю, і не залишай жертви твоєї без соли завіту Бога твого: при всякому приношенні твоєму принось [Господу Богу твоєму] сіль.","Якщо приносиш Господу приношення хлібне з перших плодів, принось у дар від перших плодів твоїх з колосся, висушеного на вогні, розтовчені зерна,","і влий на них єлею, і поклади на них ливану: це приношення хлібне;","і спалить священик у пам’ять частину зерен і єлею з усім ливаном: це жертва Господу."],"x":{"1":"2.5.11|2.6.14|17.13.9","2":"30.7.34|54.10.4|76.8.4","3":"3.18.9|30.7.33-34","5":"12.9.31","9":"2.1.9","11":"2.6.17","12":"2.23.17","13":"51.9.49","14":"5.5.11"}},{"v":["Якщо жертва його жертва мирна, і якщо він приносить з великої худоби, чоловічої або жіночої статі, нехай принесе Господу її, що не має вад,","і покладе руку свою на голову жертви своєї, і заколе її біля дверей скинії зібрання; сини ж Ааронові, священики, покроплять кров’ю на жертовник з усіх боків;","і принесе він з мирної жертви в жертву Господу жир, що покриває нутрощі, і весь жир, що на нутрощах,","і обидві нирки і жир, який на них, що на стегнах, і сальник, що на печінці; з нирками він відокремить це;","і сини Ааронові спалять це на жертовнику разом із всепаленням, яке на дровах, на вогні: це жертва, пахощі, приємні Господу.","А якщо з дрібної худоби приносить він мирну жертву Господу, чоловічої або жіночої статі, нехай принесе її, що не має вад.","Якщо з овець приносить він жертву свою, нехай представить її перед Господом,","і покладе руку свою на голову жертви своєї, і заколе її перед скинією зібрання, і сини Ааронові покроплять кров’ю її на жертовник з усіх боків;","і нехай принесе з мирної жертви у жертву Господу жир її, весь курдюк, відрізавши його по саму хребтову кістку, і жир, що покриває нутрощі, і весь жир, що на нутрощах,","і обидві нирки і жир, що на них, що на стегнах, і сальник, що на печінці; з нирками він відокремить це;","священик спалить це на жертовнику; це пожива вогню — жертва Господу.","А якщо він приносить жертву з кіз, нехай представить її перед Господом,","і покладе руку свою на голову її, і заколе її перед скинією зібрання, і покроплять сини Ааронові кров’ю її на жертовник з усіх боків;","і принесе з неї в приношення, у жертву Господу жир, що покриває нутрощі, і весь жир, що на нутрощах,","і обидві нирки і жир, що на них, що на стегнах, і сальник, що на печінці; з нирками він відокремить це","і спалить їх священик на жертовнику: це пожива вогню — приємні пахощі [Господу]; весь жир Господу.","Ця постанова вічна в роди ваші, в усіх оселях ваших; ніякого жиру і ніякої крови не їжте."],"x":{"1":"2.1.3|2.7.11","2":"1.29.16|2.1.5","3":"1.29.13:22","4":"2.4.9","5":"1.29.25|2.1.9|2.6.12","9":"2.4.35","11":"2.3.16|36.44.7","16":"1.29.13","17":"0.9.4|2.7.23:26|4.12.16|54.15.20"}},{"v":["І сказав Господь Мойсеєві, кажучи:","скажи синам Ізраїлевим: якщо яка душа згрішить помилково проти яких-небудь заповідей Господніх і зробить що-небудь, чого не треба робити;","якщо священик помазаний згрішить і зробить винним народ, — то за гріх свій, яким згрішив, нехай принесе з великої худоби тельця, без вад, Господу в жертву за гріх,","і приведе тельця до дверей скинії зібрання перед Господом, і покладе руки свої на голову тельця, і заколе тельця перед Господом;","і візьме священик помазаний, [освячений довершеним освяченням,] крови тельця і внесе її в скинію зібрання,","і вмочить священик перст свій у кров і покропить кров’ю сім разів перед Господом перед завісою святилища;","і покладе священик кров [тельця] перед Господом на роги жертовника запашного кадіння, що у скинії зібрання, а решту крови тельця виллє до підніжжя жертовника всепалень, що біля входу скинії зібрання;","і вийме з тельця за гріх весь жир його, жир, що покриває нутрощі, і весь жир, що на нутрощах,","і обидві нирки і жир, що на них, що на стегнах, і сальник на печінці; з нирками відокремить він це,","як відокремлюється з тельця жертви мирної; і спалить їх священик на жертовнику всепалення;","а шкуру тельця і все м’ясо його з головою і з ногами його, і нутрощі його і нечистоту його,","усього тельця нехай винесе поза стан на чисте місце, де висипається попіл, і спалить його вогнем на дровах; де висипається попіл, там нехай спалений буде.","Якщо ж уся громада Ізраїлева згрішить помилково і сховане буде діло від очей зібрання, і зробить що-небудь проти заповідей Господніх, чого не належало робити, і буде винна,","то, коли викритий буде гріх, яким вони згрішили, нехай від усієї громади принесуть з великої худоби тельця в жертву за гріх і приведуть його перед скинію зібрання;","і покладуть старійшини громади руки свої на голову тельця перед Господом і заколють тельця перед Господом;","І внесе помазаний священик кров тельця в скинію зібрання,","і вмочить священик перст свій у кров [тельця] і покропить сім разів перед Господом перед завісою [святилища],","і покладе кров на роги жертовника [запашного куріння], який перед лицем Господнім у скинії зібрання, а решту крови виллє до підніжжя жертовника всепалення, що при вході скинії зібрання;","і весь жир його вийме з нього і спалить на жертовнику;","і зробить з тельцем те, що робиться з тельцем за гріх: так повинен зробити з ним, і так очистить їх священик, і прощено буде їм;","і винесе тельця поза стан, і спалить його так, як спалив попереднього тельця. Це жертва за гріх громади.","А якщо згрішить начальник, і зробить помилково що-небудь проти заповідей Господа, Бога свого, чого не належало робити, і буде винен,","то, коли пізнаний буде ним гріх, яким він згрішив, нехай приведе він у жертву козла без вад,","і покладе руку свою на голову козла, і заколе його на місці, де заколюються всепалення перед Господом: це жертва за гріх;","і візьме священик перстом своїм крови від жертви за гріх і покладе на роги жертовника всепалення, а решту крови його виллє до підніжжя жертовника всепалення;","і весь жир його спалить на жертовнику, подібно як жир жертви мирної, і так очистить його священик від гріха його, і прощено буде йому.","Якщо ж хто з народу землі згрішить помилково і зробить що-небудь проти заповідей Господніх, чого не належало робити, і винен буде,","то, коли пізнаний буде ним гріх, яким він згрішив, нехай приведе він у жертву козу без вад за гріх свій, яким він згрішив,","і покладе руку свою на голову жертви за гріх, і заколють [козу] у жертву за гріх на місці, [де заколюють] жертву всепалення;","і візьме священик крови її перстом своїм, і покладе на роги жертовника всепалення, а решту крови її виллє до підніжжя жертовника;","і весь жир її відокремить, подібно як відокремлюється жир із жертви мирної, і спалить його священик на жертовнику в приємні пахощі Господу; і так очистить його священик, і прощено буде йому.","А якщо з отари овець захоче він принести жертву за гріх, нехай принесе жіночої статі, без вад,","і покладе руку свою на голову жертви за гріх, і заколе її в жертву за гріх на тому місці, де заколюють жертву всепалення;","і візьме священик перстом своїм крови від цієї жертви за гріх і покладе на роги жертовника всепалення, а решту крови її виллє до підніжжя жертовника;","і весь жир її відокремить, як відокремлюється жир вівці з жертви мирної, і спалить це священик на жертовнику в жертву Господу; і так очистить його священик від гріха, яким він згрішив, і прощено буде йому."],"x":{"2":"2.5.15","3":"2.7.7|36.45.23|64.5.21","5":"2.6.30","6":"2.8.11|2.14.7","7":"1.27.1|1.30.3|3.18.17","8":"2.2.9","9":"1.29.13|2.3.4","10":"2.3.5","11":"2.8.17|3.19.5","12":"2.6.11|75.13.11","13":"2.9.7:15|3.15.24","15":"2.3.16|13.29.23|50.26.57","17":"2.8.11|2.14.7","18":"1.40.6","20":"62.3.25|75.10.4","26":"2.3.3|2.5.13","27":"1.12.44","29":"2.1.3","31":"2.3.14|1.29.18","35":"2.5.13|2.16.18"}},{"v":["Якщо хто згрішить тим, що чув голос прокляття і був свідком, або бачив, або знав, але не оголосив, то він понесе на собі гріх.","Або якщо доторкнеться до чого-небудь нечистого, або до трупа звіра нечистого, або до трупа худоби нечистої, або до трупа гада нечистого, але не знав того, то він нечистий і винний.","Або якщо доторкнеться до нечистоти людської, яка б то не була нечистота, від якої оскверняються, і він не знав того, але після довідається, то він винний.","Або якщо хто безрозсудно устами своїми поклянеться зробити що-небудь зле або добре, яка б то не була справа, в якій люди безрозсудно клянуться, і він не знав того, але після довідався, то він винний в тому.","Якщо він винний в чому-небудь із цього, і сповідається, у чому він згрішив,","то нехай принесе Господу за гріх свій, яким він згрішив, жертву за провину з дрібної худоби, вівцю або козу, за гріх, і очистить його священик від гріха його.","Якщо ж він не в змозі принести вівці, то в провину за гріх свій нехай принесе Господу двох горлиць або двох молодих голубів, одного в жертву за гріх, а іншого у всепалення;","нехай принесе їх до священика, і [священик] представить перше того із цих птахів, що за гріх, і надломить голову її від шиї її, але не відокремить;","і покропить кров’ю цієї жертви за гріх стіну жертовника, а решту крови вицідить до підніжжя жертовника: це жертва за гріх;","а іншу вживе у всепалення за встановленням; і так очистить його священик від гріха його, яким він згрішив, і прощено буде йому.","Якщо ж він не в змозі принести двох горлиць або двох молодих голубів, нехай принесе за те, що згрішив, десяту частину ефи пшеничного борошна в жертву за гріх; нехай не ллє на неї єлею, і ливану нехай не кладе на неї, тому що це жертва за гріх;","і принесе її до священика, а священик візьме з неї повну жменю в пам’ять і спалить на жертовнику в жертву Господу: це жертва за гріх;","і так очистить його священик від гріха його, яким він згрішив в якому-небудь із цих випадків, і прощено буде йому; [залишок] же належить священикові, як приношення хлібне.","І сказав Господь Мойсеєві, кажучи:","якщо хто вчинить злочин і помилково згрішить проти посвяченого Господу, нехай за вину свою принесе Господу з отари овець барана без вад, за твоєю оцінкою, срібними сиклями по сиклю священному, у жертву за провину;","за ту святиню, проти якої він згрішив, нехай віддасть і додасть до того п’яту частку, і віддасть це священикові, і священик очистить його бараном жертви за провину, і прощено буде йому.","Якщо хто згрішить і зробить що-небудь проти заповідей Господніх, чого не належало чинити, і з невідання зробиться винним і понесе на собі гріх,","нехай принесе до священика в жертву за провину барана без вад, за оцінкою твоєю, і загладить священик провину його, в чому він переступив з невідання, і прощено буде йому.","Це жертва за провину, якою він провинився перед Господом."],"x":{"1":"4.17.4","2":"47.2.13|64.6.17|2.11.24","3":"2.11.12","4":"30.23.13|55.3.2","7":"2.12.8|52.2.24","8":"2.1.15","11":"1.16.36|2.2.1","12":"2.1.17|2.2.2","13":"2.2.3|2.4.26","15":"1.30.13","16":"2.6.7|2.22.14","18":"2.4.26"}},{"v":["І сказав Господь Мойсеєві, кажучи:","якщо хто згрішить і вчинить злочин перед Господом і стане заперечувати перед ближнім своїм у тім, що йому доручено, або у нього покладено, або ним украдено, або обмане ближнього свого,","або знайде загублене і заперечуватиме це, і поклянеться неправдиво в чому-небудь, що люди роблять і тим грішать, —","то, згрішивши і зробившись винним, він повинен повернути вкрадене, що вкрав, або відібране, що відібрав, або доручене, що йому доручено, або загублене, що він знайшов;","або якщо він у чомусь поклявся неправдиво, то повинен віддати сповна, і докласти до того п’яту частку і віддати тому, кому належить, у день приношення жертви за провину;","і за провину свою нехай принесе Господу до священика в жертву за провину із отари овець барана без вад, за оцінкою твоєю;","і очистить його священик перед Господом, і прощено буде йому, що він не зробив би, усе, в чому він став винним.","І сказав Господь Мойсеєві, говорячи:","заповідай Аарону і синам його: ось закон всепалення: всепалення нехай залишається на місці спалення на жертовнику всю ніч до ранку, і вогонь жертовника нехай горить на ньому [і не вгасає];","і нехай священик зодягнеться в лляний одяг свій, і одягне на тіло своє лляне нижнє убрання, і зніме попіл від всепалення, яке спалив вогонь на жертовнику, і покладе його біля жертовника;","і нехай зніме із себе одяг свій, і зодягне інший одяг, і винесе попіл поза стан на чисте місце;","а вогонь на жертовнику нехай горить [і] не вгасає; і нехай священик запалює на ньому дрова кожного ранку, і розкладає на ньому всепалення, і спалює на ньому жир мирної жертви;","вогонь безперестанно нехай горить на жертовнику і не вгасає.","Ось закон про приношення хлібне: [священики] сини Ааронові повинні приносити його перед Господом до жертовника;","і нехай візьме [священик] жменею своєю з приношення хлібного і пшеничного борошна і єлею і весь ливан, що на жертві, і спалить на жертовнику: це приємні пахощі, у пам’ять перед Господом;","а решту з нього нехай їдять Аарон і сини його; прісним слід їсти його на святому місці, у дворі скинії зібрання нехай їдять його;","не слід пекти його квасним. Це даю Я їм у частку з жертв Моїх. Це велика святиня, подібно як жертва за гріх і жертва за провини.","Усі нащадки Ааронові чоловічої статі можуть їсти її. Це вічна частка в роди ваші з жертв Господніх. Усе, що доторкається до них, освятиться.","І сказав Господь Мойсеєві, говорячи:","ось приношення від Аарона і синів його, яке принесуть вони Господу в день помазання його: десята частина ефи пшеничного борошна в жертву постійну, половина цього для ранку і половина для вечора;","на сковороді в єлеї вона має бути приготована; просякнуту єлеєм принось її в шматках, як розломлюється на шматки приношення хлібне; принось її в приємні пахощі Господу;","і священик, помазаний на місце його із синів його, повинен робити це: це вічний устав Господа. Уся вона повинна бути спалена;","і всяке хлібне приношення від священика все нехай буде спалене, а не з’їдене.","І сказав Господь Мойсеєві, говорячи:","скажи Аарону і синам його: ось закон про жертву за гріх: жертва за гріх повинна бути заколена перед Господом на тому місці, де заколюється всепалення; це велика святиня;","священик, який звершує жертву за гріх, повинен їсти її; вона має бути з’їдена на святому місці, у дворі скинії зібрання;","усе, що доторкнеться до м’яса її, освятиться; і якщо кров’ю її окропленим буде одяг, то забризкане омий на святому місці;","глиняну посудину, в якій вона варилася, слід розбити; якщо ж вона варилася у мідній посудині, то треба її вичистити і вимити водою;","вся чоловіча стать священичого роду може їсти її: це велика святиня [у Господа];","а всяка жертва за гріх, від якої кров вноситься в скинію зібрання для очищення у святилищі, не повинна бути з’їдена; її слід спалювати на вогні."],"x":{"2":"3.5.6","3":"1.23.4|4.22.1","5":"1.22.1|52.19.8","6":"3.5.8","7":"2.4.26","9":"1.29.38","10":"1.28.42","11":"2.4.12","12":"22.1.22","14":"2.2.1|3.15.4","15":"2.1.9","16":"2.2.3|2.8.31|36.42.13","18":"3.18.10|1.27.21|2.10.9","22":"25.50.21","25":"2.4.3|2.17.2","26":"2.6.16|38.4.8","28":"2.8.31|36.46.24","29":"2.7.6","30":"2.4.5|75.13.11"}},{"v":["Ось закон про жертву за провину: це велика святиня;","жертву за провину слід заколоти на тому місці, де заколюється всепалення, і кров’ю її кропити жертовник з усіх боків;","той, хто приносить, повинен представити з неї весь жир, курдюк і жир, що вкриває нутрощі,","і обидві нирки і жир, який на них, що на стегнах, і сальник, що на печінці; з нирками нехай він відокремить це;","і спалить це священик на жертовнику в жертву Господу: це жертва за провину.","Вся чоловіча стать священичого роду може їсти її; на святому місці слід їсти її: це велика святиня.","Як про жертву за гріх, так і про жертву за провину закон один: вона належить священикові, який очищає через неї.","І коли священик приносить чиюсь жертву всепалення, шкіра від жертви всепалення, яку він приносить, належить священикові;","і всяке приношення хлібне, яке печене в печі, і всяке приготоване у горщику або на сковороді, належить священикові, який приносить його;","і всяке приношення хлібне, змішане з єлеєм і сухе, належить усім синам Аароновим, як одному, так і іншому.","Ось закон про жертву мирну, яку приносять Господу:","якщо хто в подяку приносить її, то при жертві подяки він повинен принести прісні хліби, змішані з єлеєм, і прісні коржі, помазані єлеєм, і пшеничне борошно, просякнуте єлеєм, хліби, змішані з єлеєм;","крім коржів, нехай він приносить у приношення своє квасний хліб, при мирній жертві подячній;","одне що-небудь з усього приношення свого нехай принесе він для возношення Господу: це належить священикові, який кропить кров’ю мирної жертви;","м’ясо мирної жертви подяки слід з’їсти в день приношення її, не слід залишати від нього до ранку.","Якщо ж хто приносить жертву за обітницею, або від ревности, то жертву його слід їсти в день приношення, і на другий день те, що залишиться від неї, їсти можна,","а що залишилося від жертовного м’яса до третього дня, треба спалити на вогні;","якщо ж будуть їсти м’ясо мирної жертви на третій день, то вона не буде благоприємна; хто її принесе, тому ні у що не буде ставитися: це осквернення, і хто буде їсти її, той понесе на собі гріх;","м’яса цього, якщо воно доторкнеться до чого-небудь нечистого, не слід їсти, але треба спалити його на вогні; а м’ясо чисте може їсти всякий чистий;","якщо ж яка душа, маючи на собі нечистоту, буде їсти м’ясо мирної жертви Господньої, то знищиться душа та з народу свого;","і якщо яка душа, доторкнувшись до чого-небудь нечистого, до нечистоти людської, або до нечистої худоби, або до якого-небудь нечистого плазуна, буде їсти м’ясо мирної жертви Господньої, то знищиться душа та з народу свого.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: ніякого жиру ні з вола, ні з вівці, ні з козла не їжте.","Жир з мертвого і жир з роздертого звіром можна вживати на всяку справу; а їсти не їжте його;","тому що, хто буде їсти жир з худоби, що приноситься в жертву Господу, знищиться душа та з народу свого;","і ніякої крови не їжте в усіх оселях ваших ні з птахів, ні з худоби;","а хто буде їсти яку-небудь кров, знищиться душа та з народу свого.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: хто представляє мирну жертву свою Господу, той з мирної жертви частину повинен принести для приношення Господу;","своїми руками повинен він принести в жертву Господу: жир із грудьми повинен він принести [і сальник на печінці], потрясаючи грудьми перед лицем Господнім;","жир спалить священик на жертовнику, а груди належать Ааронові й синам його;","і праве плече, як возношення, з мирних жертв ваших віддавайте священикові:","хто з синів Ааронових приносить кров із мирної жертви і жир, тому і праве плече в частку;","бо Я беру від синів Ізраїлевих з мирних жертв їхніх груди потрясання і плече возношення, і віддаю їх Аарону священику і синам його у вічну частку від синів Ізраїлевих.","Ось частина Аарону і частина синам його з жертв Господніх від дня, коли вони стануть перед Господом для священнодійства,","яку повелів Господь давати їм від дня помазання їх від синів Ізраїлевих. Це вічна постанова в роди їх. —","Ось закон про всепалення, про приношення хлібне, про жертву за гріх, про жертву за провини, про жертву посвячення і про жертву мирну,","який дав Господь Мойсею на горі Синаї, коли повелів синам Ізраїлевим, у пустелі Синайській, приносити Господу приношення їх."],"x":{"1":"2.5.6","2":"2.1.5|2.6.25","3":"2.3.3","4":"2.3.4:10","6":"2.6.18","7":"2.14.13","8":"2.1.6","9":"2.2.3","10":"2.2.5|2.5.11|2.6.22","11":"2.3.2","12":"2.22.29|13.29.31|25.115.8","15":"2.19.5|2.22.30|63.10.18","16":"3.30.3","17":"2.19.6","19":"8.20.26","20":"0.17.14","21":"2.11.4","23":"2.3.17","26":"0.9.4|2.3.17","30":"1.29.24","32":"1.30.15","34":"1.29.27|3.18.11|63.9.13","37":"2.16.6|2.27.34"}},{"v":["І сказав Господь Мойсеєві, говорячи:","візьми Аарона і синів його з ним, і одежу і єлей помазання, і тельця для жертви за гріхи і двох баранів, і кошик опрісноків,","і збери всю громаду при вході до скинії зібрання.","Мойсей зробив так, як повелів йому Господь, і зібралася громада при вході у скинію зібрання.","І сказав Мойсей до громади: ось що повелів Господь зробити.","І привів Мойсей Аарона і синів його й обмив їх водою;","і поклав на нього хітон, і оперезав його поясом, і вдягнув на нього верхню ризу, і поклав на нього ефод, і оперезав його поясом ефода і прикріпив ним ефод на ньому,","і поклав на нього наперсник, і на наперсник поклав урим і тумим,","і поклав на голову його кидар, а на кидар з передньої сторони його поклав поліровану дощечку, діадему святині, як повелів Господь Мойсеєві.","І взяв Мойсей єлей помазання, і помазав скинію й усе, що в ній, і освятив це;","і покропив ним жертовник сім разів, і помазав жертовник й усе приладдя його й умивальник і підніжжя його, щоб освятити їх;","і полив [Мойсей] єлей помазання на голову Аарона і помазав його, щоб освятити його.","І привів Мойсей синів Ааронових, і вдяг їх у хітони, і оперезав їх поясом, і поклав на них кидари, як повелів Господь Мойсеєві.","І привів [Мойсей] тельця для жертви за гріх, і Аарон та сини його поклали руки свої на голову тельця за гріх;","і заколов його [Мойсей] і взяв крови, і перстом своїм поклав на роги жертовника з усіх боків, і очистив жертовник, а решту крови вилив до підніжжя жертовника, і освятив його, щоб зробити його чистим.","І взяв [Мойсей] весь жир, який на нутрощах, і сальник на печінці, і обидві нирки і жир їх, і спалив Мойсей на жертовнику;","а тельця і шкуру його, і м’ясо його, і нечистоту його спалив на вогні поза станом, як повелів Господь Мойсеєві.","І привів [Мойсей] барана для всепалення, і поклали Аарон та сини його руки свої на голову барана;","і заколов його Мойсей і покропив кров’ю жертовник з усіх боків;","і розсік барана на частини, і спалив Мойсей голову і частини і жир,","а нутрощі і ноги обмив водою, і спалив Мойсей усього барана на жертовнику: це всепалення для приємних пахощів, це жертва Господу, як повелів Господь Мойсеєві.","І привів [Мойсей] іншого барана, барана освячення, і поклали Аарон та сини його руки свої на голову барана;","і заколов його Мойсей, і взяв крови його, і поклав на край правого вуха Ааронового і на великий палець правої руки його і на великий палець правої ноги його.","І привів Мойсей синів Ааронових, і поклав крови на край правого вуха їх і на великий палець правої руки їх і на великий палець правої ноги їх, і покропив Мойсей кров’ю жертовник з усіх боків.","І взяв [Мойсей] жир і курдюк і весь жир, який на нутрощах, і сальник на печінці, і обидві нирки і жир їх і праве плече;","і з кошика з опрісноками, що перед Господом, взяв один опріснок і один хліб з єлеєм і один корж, і поклав на жир і на праве плече;","і поклав усе це на руки Аарону і на руки синам його, і приніс це, потрясаючи перед лицем Господнім;","і взяв це Мойсей з рук їхніх і спалив на жертовнику з усепаленням: це жертва посвячення для приємних пахощів, це жертва Господу.","І взяв Мойсей груди і приніс їх, потрясаючи перед лицем Господнім: це була частка Мойсеєва від барана посвячення, як повелів Господь Мойсеєві.","І взяв Мойсей єлею помазання і крови, що на жертовнику, і покропив Аарона й одяг його, і синів його й одяг синів його з ним; і так освятив Аарона й одежу його, і синів його й одежу синів його з ним.","І сказав Мойсей Аарону і синам його: зваріть м’ясо при вході у скинію зібрання і там їжте його з хлібом, що у кошику посвячення, як мені повелено і сказано: Аарон і сини його повинні їсти його;","а залишки м’яса і хліба спаліть на вогні.","Сім днів не відходьте від дверей скинії зібрання, доки не виповняться дні посвячення вашого, тому що сім днів повинно відбуватися посвячення ваше;","як сьогодні було зроблено, так повелів Господь робити для очищення вас;","при вході у скинію зібрання будьте день і ніч упродовж семи днів і будьте на сторожі у Господа, щоб не вмерти, тому що так мені повелено [від Господа Бога].","І виконав Аарон і сини його все, що повелів Господь через Мойсея."],"x":{"2":"1.28.1|2.9.18:22","6":"1.28.1|1.40.12","10":"1.30.25|3.7.1","12":"1.29.7|3.35.25|25.132.2|30.45.18","14":"1.29.10","15":"13.29.22|1.29.16","16":"2.3.4","18":"1.29.15","21":"1.29.18|2.1.9","22":"1.29.19","23":"2.14.14","25":"1.29.22","26":"1.29.23","28":"2.1.9","29":"1.29.24|2.7.33","30":"1.29.21|30.45.18","31":"1.29.32|2.24.9|50.12.4|51.2.26|52.6.4","35":"2.10.7"}},{"v":["У восьмий день покликав Мойсей Аарона і синів його і старійшин Ізраїлевих","і сказав Аарону: візьми собі з волів тельця в жертву за гріх і барана у всепалення, обох без вад, і представ перед лице Господнє;","і синам Ізраїлевим скажи: візьміть козла в жертву за гріх, [і барана,] і тельця, і агнця, однолітніх, без вад, у всепалення,","і вола й барана в жертву мирну, щоб звершити жертвоприношення перед лицем Господнім, і приношення хлібне, змішане з єлеєм, тому що сьогодні Господь явиться вам.","І принесли те, що наказав Мойсей, перед скинію зібрання, і прийшла вся громада і стала перед лицем Господнім.","І сказав Мойсей: ось що повелів Господь зробити, і явиться вам слава Господня.","І сказав Мойсей Аарону: приступи до жертовника і зверши жертву твою за гріх і всепалення твоє, й очисти себе і народ, і зроби приношення від народу, й очисти їх, як повелів Господь.","І приступив Аарон до жертовника і заколов тельця, який за нього, у жертву за гріх:","сини Ааронові піднесли йому кров, і він омочив перст свій у крові і поклав на роги жертовника, а решту крови вилив до підніжжя жертовника,","а жир і нирки і сальник на печінці від жертви за гріх спалив на жертовнику, як повелів Господь Мойсеєві;","м’ясо ж і шкуру спалив на вогні поза станом.","І заколов всепалення, і сини Ааронові піднесли йому кров; він покропив нею жертовник з усіх боків;","і принесли йому всепалення у шматках і голову, і він спалив на жертовнику,","а нутрощі і ноги вимив і спалив з усепаленням на жертовнику.","І приніс приношення від народу, і взяв від народу козла за гріх, і заколов його, і приніс його в жертву за гріх, як і попереднього.","І приніс всепалення і зробив його за уставом.","І приніс приношення хлібне, і наповнив ним руки свої, і спалив на жертовнику зверх ранкового всепалення.","І заколов вола й барана, які від народу, у жертву мирну; і сини Ааронові піднесли йому кров, і він покропив нею жертовник з усіх боків;","піднесли і жир з вола, і з барана курдюк, і [жир], що покриває [нутрощі], нирки і сальник на печінці,","і поклали жир на груди, і він спалив жир на жертовнику;","груди ж і праве плече приніс Аарон, потрясаючи перед лицем Господнім, як повелів Мойсей.","І підняв Аарон руки свої, звернувшись до народу, і благословив його, і зійшов, звершивши жертву за гріх, всепалення і жертву мирну.","І ввійшли Мойсей і Аарон у скинію зібрання, і вийшли, і благословили народ. І явилася слава Господня всьому народові:","і вийшов вогонь від Господа і спалив на жертовнику всепалення і жир; і бачив весь народ, і викликнув з радости, й упав на лице своє."],"x":{"2":"1.29.1","3":"2.4.13|2.1.5","7":"2.16.6|75.7.27","10":"1.29.22|2.3.10","11":"2.4.11","13":"2.1.6","15":"64.5.21","17":"2.2.1|1.29.38-40|3.28.4","21":"1.29.24","22":"3.6.23|1.20.24","24":"22.2.10"}},{"v":["Надав і Авиуд, сини Ааронові, узяли кожен свою кадильницю, і поклали в них вогню, і вклали в нього куріння, і принесли перед Господом вогонь чужий, якого Він не велів їм;","і вийшов вогонь від Господа і спалив їх, і померли вони перед лицем Господнім.","І сказав Мойсей Аарону: ось про що говорив Господь, коли сказав: у тих, хто наближається до Мене, освячусь і перед усім народом прославлюсь. Аарон мовчав.","І покликав Мойсей Мисаїла й Елцафана, синів Узиїла, дядька Ааронового, і сказав їм: підіть, винесіть братів ваших зі святилища за стан.","І пішли і винесли їх у хітонах їхніх за стан, як сказав Мойсей.","Аарону ж і Єлеазару й Іфамару, синам його, Мойсей сказав: голів ваших не оголюйте й одягу вашого не роздирайте, щоб вам не померти і не навести гніву на всю громаду; але брати ваші, весь дім Ізраїлів, можуть плакати за спаленими, яких спалив Господь,","і з дверей скинії зібрання не виходьте, щоб не померти вам, тому що на вас єлей помазання Господнього. І зробили за словом Мойсея.","І сказав Господь Аарону, говорячи:","вина і міцних напоїв не пий ти і сини твої з тобою, коли входите в скинію зібрання, [або приступаєте до жертовника,] щоб не померти. Це вічна постанова в роди ваші,","щоб ви могли відрізняти священне від несвященного і нечисте від чистого,","і навчати синів Ізраїлевих усіх уставів, про які говорив їм Господь через Мойсея.","І сказав Мойсей Аарону та Єлеазару й Іфамару, які залишилися з синів його: візьміть приношення хлібне, що залишилося від жертв Господніх, і їжте його прісним біля жертовника, бо це велика святиня;","і їжте його на святому місці, бо це частка твоя і частка синів твоїх від жертв Господніх: так мені наказано [від Господа];","і груди потрясіння і плече підношення їжте на чистому місці, ти і сини твої і дочки твої з тобою, тому що це дано в частку тобі й у частку синам твоїм з мирних жертв синів Ізраїлевих;","плече підношення і груди потрясання повинні вони приносити з жертвами жиру, потрясаючи перед лицем Господнім, і нехай буде це вічною часткою тобі і синам твоїм [і дочкам твоїм] з тобою, як повелів Господь [Мойсеєві].","І козла жертви за гріхи шукав Мойсей, і ось, він спалений. І розгнівався [Мойсей] на Єлеазара й Іфамара, які залишилися з синів Ааронових, і сказав:","чому ви не їли жертви за гріх на святому місці? бо вона святиня велика, і вона дана вам, щоб знімати гріхи з громади й очищати їх перед Господом;","ось, кров її не внесена всередину святилища, а ви повинні були їсти її на святому місці, як повелено мені.","Аарон сказав Мойсеєві: ось, сьогодні принесли вони жертву свою за гріх і всепалення своє перед Господом, і це трапилось зі мною; якщо я сьогодні з’їм жертву за гріх, чи буде це вгодно Господу?","І почув Мойсей і схвалив."],"x":{"1":"3.3.4|3.26.61|12.24.2","3":"1.19.22|36.42.13|56.4.17","5":"54.5.6:10","6":"2.13.45|2.21.10","9":"36.44.21|71.3.3|73.1.7","10":"36.44.23|75.5.14|2.11.1-47","11":"4.33.10|49.2.4","12":"2.2.3|2.6.16","13":"2.2.3|2.6.16","14":"2.9.21","15":"1.29.27","16":"22.2.11","17":"2.6.26|1.28.38"}},{"v":["І сказав Господь Мойсеєві й Ааронові, говорячи їм:","скажіть синам Ізраїлевим: ось тварини, що їх можна вам їсти з усієї худоби на землі:","усяку худобу, у якої роздвоєні копита і на копитах глибокий розріз, і яка жує жуйку, їжте;","тільки цих не їжте з тих, що жують жуйку і що мають роздвоєні копита: верблюда, тому що він жує жуйку, але копита в нього не роздвоєні, нечистий він для вас;","і тушканчика, тому що він жує жуйку, але копита в нього не роздвоєні, нечистий він для вас,","і зайця, тому що він жує жуйку, але копита в нього не роздвоєні, нечистий він для вас;","і свині, тому що копита в неї роздвоєні і на копитах розріз глибокий, але вона не жує жуйки, нечиста вона для вас;","м’яса їх не їжте і до трупів їх не доторкайтеся; нечисті вони для вас.","З усіх тварин, які у воді, їжте цих: у яких є пір’я і луска у воді, чи у морях, або ріках, тих їжте;","а всі ті, у яких немає пір’я і луски, чи у морях, або ріках, із усіх, що плавають у водах і з усього, що живе у водах, нечисте для вас;","вони повинні бути нечистими для вас: м’яса їх не їжте і трупами їх гребуйте;","усі тварини, в яких немає пір’я і луски у воді, нечисте для вас.","Із птахів же цурайтеся цих [не слід їх їсти, нечисті вони]: орла, грифа і морського орла,","шуліку і сокола з породою його,","усякого ворона з породою його,","страуса, сови, чайки і яструба з породою його,","пугача, риболова й ібіса,","лебедя, пелікана і сипа,","чаплі, зуя з породою його, удода і нетопиря.","Усі тварини, що плазують, крилаті, що ходять на чотирьох ногах, нечисті для нас;","з усіх плазунів, крилатих, що ходять на чотирьох ногах, тих тільки їжте, у яких є гомілки вище ніг, щоб скакати ними по землі;","цих їжте з них: сарану з її породою, солам з її породою, харгол з її породою і хагаб з її породою.","Всяке інше, що плазує, крилате, у якого чотири ноги, нечисте для вас;","від них ви будете нечисті: усякий, хто доторкнеться до трупа їх, нечистий буде до вечора;","і всякий, хто візьме труп їх, повинен вимити одяг свій і буде нечистий до вечора.","Усяка худоба, у якої копита раздвоєні, але немає глибокого розрізу, і яка не жує жуйки, нечиста для вас: усякий, хто доторкнеться до неї, буде нечистий [до вечора].","З усіх звірів чотириногих ті, які ходять на лапах, нечисті для вас: усякий, хто доторкнеться до трупа їх, нечистий буде до вечора;","хто візьме труп їх, той повинен вимити одяг свій і буде нечистий до вечора: нечисті вони для вас.","Ось що нечисте для вас з тварин, які плазують по землі: кріт, миша, ящірка з її породою,","анака, хамелеон, летаа, хомет і тиншемет, —","ці нечисті для вас з усіх плазунів: усякий, хто доторкнеться до них мертвих, нечистий буде до вечора.","І все, на що впаде яке-небудь з них мертве, всяка дерев’яна посудина, або одяг, або шкіра, або мішок, і всяка річ, що вживається для справи, будуть нечисті: у воду треба покласти їх, і нечисті будуть до вечора, потім будуть чисті;","якщо ж яке-небудь з них упаде в якусь глиняну посудину, то те, що знаходиться в ньому, буде нечисте, і саму [посудину] розбийте.","Всяка їжа, яку їдять, на якій була вода з такої посудини, нечиста буде [для вас], і всяке питво, яке п’ють, у всякій такій посудині нечисте буде.","Все, на що впаде що-небудь від трупа їхнього, нечисте буде: піч і вогнище слід розламати, вони нечисті; і вони повинні бути нечисті для вас;","тільки джерело і колодязь, що містить воду, залишаються чистими; а хто доторкнеться до трупа їх, той нечистий.","І якщо що-небудь від трупа їх упаде на яке-небудь насіння, яке сіють, то воно чисте;","якщо ж тоді, коли вода налита на насіння, упаде на нього що-небудь від трупа їх, то воно нечисте для вас.","І коли помре яка-небудь худоба, яка вживається вами в їжу, то той, хто доторкнеться до трупа її, нечистий буде до вечора;","і той, хто буде їсти мертвечину її, повинен вимити одяг свій і нечистий буде до вечора; і той, хто понесе труп його, повинен вимити одяг свій і нечистий буде до вечора.","Всяка тварина, що плазує по землі, нечиста для вас, не слід їсти її;","всього, що плазує на череві, і всього, що ходить на чотирьох ногах, і багатоногих з тварин, що плазують по землі, не їжте, бо вони нечисті;","не оскверняйте душ ваших якою-небудь твариною, що плазує, і не робіть себе через них нечистими, щоб бути через них нечистими,","бо Я — Господь Бог ваш: освячуйтеся і будьте святими, бо Я [Господь, Бог ваш] святий; і не оскверняйте душ ваших якою-небудь твариною, що плазує по землі,","тому що Я — Господь, Який вивів вас із землі Єгипетської, щоб бути вашим Богом. Отже, будьте святими, тому що Я святий.","Ось закон про худобу, про птахів, про всіх тварин, що живуть у водах, і про всіх тварин, що плазують по землі,","щоб відрізняти нечисте від чистого, і тварин, яких можна їсти, від тварин, яких їсти не можна."],"x":{"2":"4.14.4","3":"0.1.30|62.14.14","7":"22.6.18","9":"4.14.9","13":"4.14.12-29","24":"2.5.2|47.2.14","32":"2.15.12","33":"2.6.28","40":"2.17.15|4.14.21","44":"2.19.2|2.20.7|56.1.16","45":"0.17.7|2.20.7","47":"50.15.17"}},{"v":["І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: якщо жінка зачне і народить немовля чоловічої статі, то вона нечиста буде сім днів; як у дні нечистоти від місячних її, вона буде нечиста;","у восьмий же день обріжеться у нього крайня плоть його;","і тридцять три дні повинна вона сидіти, очищаючись від крови своєї; ні до чого священного не повинна доторкатися і до святилища не повинна приходити, доки не виповняться дні очищення її.","Якщо ж вона народить немовля жіночої статі, то під час очищення свого вона буде нечиста два тижні, і шістдесят шість днів повинна сидіти, очищаючись від крови своєї.","Після закінчення днів очищення свого за сина або за дочку вона повинна принести однолітнього агнця у всепалення і молодого голуба або горлицю в жертву за гріх, до входу в скинію зібрання до священика;","він принесе це перед Господом і очистить її, і вона буде чиста від течі крови її. Ось закон про тих, хто народжує дитину чоловічої або жіночої статі.","Якщо ж вона не в змозі принести агнця, те нехай візьме двох горлиць або двох молодих голубів, одного у всепалення, а іншого в жертву за гріх, і очистить її священик, і вона буде чиста."],"x":{"2":"52.2.22","3":"0.17.10|52.2.21|53.7.22","6":"2.5.7","8":"52.2.24|2.5.7"}},{"v":["І сказав Господь Мойсеєві й Аарону, говорячи:","коли в кого з’явиться на шкірі тіла його пухлина, або лишаї, або пляма, і на шкірі тіла його зробиться наче виразка прокази, то слід привести його до Аарона священика, або до одного із синів його, священиків;","священик огляне виразку на шкірі тіла, і якщо волосся на виразці змінилося на біле, і виразка виявилася заглибленою у шкіру тіла його, то це виразка прокази; священик, оглянувши його, оголосить його нечистим.","А якщо на шкірі тіла його пляма біла, але вона не виявиться заглибленою у шкіру, і волосся на ній не змінилося на біле, то священик повинен замкнути того, хто має виразку, на сім днів;","у сьомий день священик огляне його, і якщо виразка залишається у своєму вигляді і не поширюється виразка по шкірі, то священик повинен замкнути його на інші сім днів;","у сьомий день знову священик огляне його, і якщо виразка менше помітна і не поширилася виразка по шкірі, то священик повинен оголосити його чистим: це лишаї, і нехай вимиє одежу свою, і буде чистим.","Якщо ж лишаї стануть поширюватися по шкірі, після того як він з’являвся до священика для очищення, то він удруге повинен з’явитися до священика;","священик, побачивши, що лишаї поширюються по шкірі, оголосить його нечистим: це проказа.","Якщо буде на кому виразка прокази, то слід привести його до священика;","священик огляне, і якщо пухлина на шкірі біла, і волосся змінилося на біле, і на пухлині живе м’ясо,","то це застаріла проказа на шкірі тіла його; і священик оголосить його нечистим і ізолює його, бо він нечистий.","Якщо ж проказа розцвіте на шкірі, і покриє проказа всю шкіру хворого від голови його до ніг, скільки можуть бачити очі священика,","і побачить священик, що проказа покрила все тіло його, то він оголосить хворого чистим, тому що все перетворилося на біле: він чистий.","Коли ж виявиться на ньому живе м’ясо, то він нечистий;","священик, побачивши живе м’ясо, оголосить його нечистим; живе м’ясо нечисте: це проказа.","Якщо ж живе м’ясо зміниться і перетвориться на біле, нехай він прийде до священика;","священик огляне його, і якщо виразка перетвориться на біле, священик оголосить хворого чистим; він чистий.","Якщо в кого на шкірі тіла був нарив і загоївся,","і на місці нариву з’явилася біла пухлина, чи пляма біла або червонувата, то він повинен з’явитися до священика;","священик огляне його, і якщо воно виявиться нижче шкіри, і волосся його змінилося на біле, то священик оголосить його нечистим: це виразка прокази, вона розцвіла на нариві;","якщо ж священик побачить, що волосся на ній не біле, і вона не нижче шкіри, і притому мало примітна, то священик ізолює його на сім днів;","якщо вона стане дуже поширюватися по шкірі, то священик оголосить його нечистим: це виразка;","якщо ж пляма залишається на своєму місці і не поширюється, то це запалення нариву, і священик оголосить його чистим.","Або якщо в кого на шкірі тіла буде опік, і на опіку, що загоївся, виявиться червонувата або біла пляма,","і священик побачить, що волосся на плямі змінилося на біле, і вона виявиться заглибленою у шкіру, то це проказа, вона розцвіла на опіку; і священик оголосить його нечистим: це виразка прокази;","якщо ж священик побачить, що волосся на плямі не біле, і вона не нижче шкіри, і притому мало помітна, то священик ізолює його на сім днів;","у сьомий день священик огляне його, і якщо вона дуже поширюється по шкірі, то священик оголосить його нечистим: це виразка прокази;","якщо ж пляма залишається на своєму місці і не поширюється по шкірі, і притому мало примітна, те це пухлина від опіку; священик оголосить його чистим, бо це запалення від опіку.","Якщо у чоловіка або у жінки буде виразка на голові або на бороді,","і огляне священик виразку, і вона виявиться заглибленою в шкірі, і волосся на ній жовтувате тонке, то священик оголосить їх нечистими: це паршивість, це проказа на голові або на бороді;","якщо ж священик огляне виразку паршивости і вона не виявиться заглибленою в шкірі, і волосся на ній не чорне, то священик того, хто має виразку паршивости, ізолює на сім днів;","у сьомий день священик огляне виразку і, якщо паршивість не поширюється і немає на ній жовтуватого волосся, і паршивість не виявиться заглибленою в шкірі,","то хворого слід обстригти, але паршивого місця не обстригати, і священик повинен паршивого вдруге ізолювати на сім днів;","у сьомий день священик огляне паршивість, і якщо паршивість не поширюється на шкірі і не виявиться заглибленою в шкірі, то священик оголосить його чистим; нехай він вимиє одежу свою, і буде чистий.","Якщо ж після очищення його буде дуже поширюватися паршивість по шкірі,","і священик побачить, що паршивість поширюється по шкірі, то священик нехай не шукає жовтуватого волосся: він нечистий.","Якщо ж паршивість залишається у своєму вигляді, і показується на ній волосся чорне, то паршивість минула, він чистий; священик оголосить його чистим.","Якщо у чоловіка або у жінки на шкірі тіла їх будуть плями, плями білі,","і священик побачить, що на шкірі тіла їх плями блідо-білі, то це лишай, що розцвів на шкірі: він чистий.","Якщо в кого на голові вилізло волосся, то це плішивий: він чистий;","а якщо на передній частині голови вилізло волосся, то це лисий: він чистий.","Якщо ж на пліші або на лисині буде біла або червонувата пляма, то на пліші його або на лисині його розцвіла проказа;","священик огляне його, і якщо побачить, що пухлина виразки біла або червонувата на пліші його або на лисині його, і на вигляд схожа на проказу шкіри тіла,","то він прокажений, нечистий він; священик повинен оголосити його нечистим, у нього на голові виразка.","У прокаженого, на якому ця виразка, повинна бути розідрана одежа, і голова його повинна бути не покрита, і до вуст він повинен бути закритим і кричати: нечистий! нечистий!","В усі дні, поки на ньому виразка, він повинен бути нечистим, нечистий він; він повинен жити окремо, поза станом житло його.","Якщо виразка прокази буде на одязі, на одязі вовняному, або на одязі лляному,","або на основі, або на утоці з льону або вовни, або на шкірі, або на якому-небудь виробі шкіряному,","і пляма буде зеленкувата або червонувата на одязі, або на шкірі, або на основі, або на утоці, або на якій-небудь шкіряній речі, — то це виразка прокази: треба показати її священикові;","священик огляне виразку і ізолює заражене виразкою на сім днів;","у сьомий день огляне священик заражене, і якщо виразка поширилася по одягу, або по основі, або по утоку, або по шкірі, або по якому-небудь виробу, зробленому зі шкіри, то це проказа їдка, виразка нечиста;","він повинен спалити одяг, або основу, або утік вовняний або лляний, або яку б то не було шкіряну річ, на якій буде виразка, бо це проказа їдка: слід спалити на вогні.","Якщо ж священик побачить, що виразка не поширилася по одягу, або по основі, або по утоку, або на якій би то не було шкіряній речі,","то священик накаже вимити те, на чому виразка, і вдруге ізолює на сім днів;","якщо після обмивання зараженої речі священик побачить, що виразка не змінила вигляду свого і не поширилася виразка, то вона нечиста, спали її на вогні; це виїдена ямка на лицьовій стороні або на вивороті;","якщо ж священик побачить, що виразка після обмивання її зробилася менш примітною, то священик нехай відірве її від одежі, або від шкіри, або від основи, або від утоку.","Якщо ж вона знову покажеться на одязі, або на основі, або на утоці, або на якій-небудь шкіряній речі, то це виразка, що розквітає: спали на вогні те, на чому виразка.","Якщо ж одяг, або основу, або утік, або яку-небудь шкіряну річ вимиєш, і зійде з них виразка, то слід вимити їх удруге, і вони будуть чисті.","Ось закон про виразку прокази на одязі вовняному або лляному, або на основі і на утоці, або на якій-небудь шкіряній речі, як оголосити її чистою або нечистою."],"x":{"2":"2.14.3|4.24.8|50.8.4","3":"3.14.12","6":"44.3.19","9":"2.14.3|4.24.8","12":"1.9.9|31.1.6","13":"25.31.5|25.37.4|52.18.13-14","34":"76.7.14","46":"11.15.5|63.5.11|65.5.19:21"}},{"v":["І сказав Господь Мойсеєві, говорячи:","ось закон про прокаженого, коли потрібно його очистити: приведуть його до священика;","священик вийде геть зі стану, і якщо священик побачить, що прокажений зцілився від хвороби прокаження,","то священик накаже взяти для того, хто очищається, двох птахів живих чистих, кедрового дерева, червлену нитку та ісопу,","і накаже священик заколоти одного птаха над глиняною посудиною, над живою водою;","а сам він візьме живого птаха, кедрове дерево, червлену нитку та ісоп, і омочить їх і живого птаха у крові птаха, заколотого над живою водою,","і покропить того, хто очищається від прокази, сім разів, і оголосить його чистим, і пустить живого птаха в поле.","Той, хто очищається, омиє одежу свою, обстриже усе волосся своє, омиється водою, і буде чистий; потім увійде в стан і пробуде сім днів поза наметом своїм;","у сьомий день поголить усе волосся своє, голову свою, бороду свою, брови очей своїх, усе волосся своє поголить, і вимиє одежу свою, і обмиє тіло своє водою, і буде чистий;","у восьмий день візьме він двох баранів [однолітніх] без вад, і одну вівцю однолітню без вад, і три десятих частини ефи пшеничного борошна, змішаного з єлеєм, для приношення хлібного, і один лог єлею;","священик, який очищає, поставить людину, що очищається, з ними перед Господом при вході у скинію зібрання;","і візьме священик одного барана, і представить його в жертву за провину, і лог єлею, і принесе це, потрясаючи перед Господом;","і заколе барана на тому місці, де заколюють жертву за гріх і всепалення, на місці святому, тому що ця жертва за провину, подібно до жертви за гріх, належить священикові: це велика святиня;","і візьме священик крови жертви за провину, і покладе священик на край правого вуха того, хто очищається, і на великий палець правої руки його і на великий палець правої ноги його;","і візьме священик з лога єлею і поллє на ліву свою долоню;","й омочить священик правий перст свій у єлей, який на лівій долоні його, і покропить єлеєм з перста свого сім разів перед лицем Господа;","єлей же, що залишився, який на долоні його, покладе священик на край правого вуха того, хто очищається, на великий палець правої руки його і на великий палець правої ноги його, на місця, де кров жертви за провину;","а решту єлею, який на долоні священика, покладе він на голову того, хто очищається, і очистить його священик перед лицем Господа.","І звершить священик жертву за гріх, і очистить того, хто очищається, від нечистоти його; після того заколе жертву всепалення;","і покладе священик всепалення і приношення хлібне на жертовник; і очистить його священик, і він буде чистий.","Якщо ж він бідний і не має достатку, то нехай візьме одного барана в жертву за провину для потрясання, щоб очистити себе, і одну десяту частину ефи пшеничного борошна, змішаного з єлеєм, для приношення хлібного, і лог єлею,","і двох горлиць або двох молодих голубів, що дістане рука його, одного з птахів у жертву за гріх, а іншого у всепалення;","і принесе їх у восьмий день очищення свого до священика до входу у скинію зібрання, перед лице Господа;","священик візьме барана жертви за провину і лог єлею, і принесе це священик, потрясаючи перед Господом;","і заколе барана в жертву за провину, і візьме священик крови жертви за провину, і покладе на край правого вуха того, хто очищається, і на великий палець правої руки його і на великий палець правої ноги його;","і наллє священик єлею на ліву свою долоню,","і єлеєм, що на лівій долоні його, покропить священик правим перстом своїм сім разів перед лицем Господнім;","і покладе священик єлей, що на долоні його, на край правого вуха того, хто очищається, на великий палець правої руки його і на великий палець правої ноги його, на місця, де кров жертви за провину;","а решту єлею, що на долоні священика, покладе він на голову того, хто очищається, щоб очистити його перед лицем Господа;","і принесе одну з горлиць або одного з молодих голубів, що дістане рука того, хто очищається,","з того, що дістане рука його, одного птаха в жертву за гріх, а іншого у всепалення, разом із приношенням хлібним; і очистить священик того, хто очищається, перед лицем Господа.","Ось закон про прокаженого, який в час очищення свого не має достатку.","І сказав Господь Мойсеєві й Аарону, говорячи:","коли ввійдете в землю Ханаанську, яку Я даю вам у володіння, і Я наведу виразку прокази на доми в землі володіння вашого,","тоді той, чий дім, повинен піти і сказати священикові: у мене в домі показалася ніби виразка.","Священик накаже спорожнити дім, раніше ніж увійде священик оглядати виразку, щоб не зробилося нечистим усе, що в домі; після цього прийде священик оглядати дім.","Якщо він, оглянувши виразку, побачить, що виразка на стінах дому складається з зеленкуватих або червонуватих ямок, які виявляться заглибленими у стіні,","то священик вийде з дому до дверей дому і замкне дім на сім днів.","У сьомий день знову прийде священик і, якщо побачить, що виразка поширилася по стінах дому,","то священик накаже виламати камені, на яких виразка, і кинути їх поза містом на місце нечисте;","а дім усередині нехай весь вишкребуть, і обмазку, яку вишкребуть, висиплять поза містом на місце нечисте;","і візьмуть інші камені, і вставлять замість тих каменів, і візьмуть іншу глину, і обмажуть дім.","Якщо виразка знову з’явиться і буде цвісти на домі після того, як виламали камені і обшкребли дім і обмазали,","то священик прийде й огляне, і якщо виразка на домі поширилася, то це їдка проказа на домі, нечистий він;","слід розламати цей дім, і камені його і дерево його і всю глину дому винести поза місто на місце нечисте;","хто входить у дім за весь час, коли він замкнений, той нечистий до вечора;","і хто спить у домі тім, той повинен вимити одежу свою [і нечистий буде до вечора]; і хто їсть у домі тім, той повинен вимити одежу свою [і нечистий буде до вечора].","Якщо ж священик прийде і побачить, що виразка на домі не поширилася після того, як обмазали дім, то священик оголосить дім чистим, бо виразка минула.","І щоб очистити дім, візьме він два птахи, кедрового дерева, червлену нитку та ісопу,","і заколе одного птаха над глиняною посудиною, над живою водою;","і візьме кедрове дерево та ісоп, і червлену нитку і живого птаха, і омочить їх у крові птаха заколотого й у живій воді, і покропить дім сім разів;","і очистить дім кров’ю птаха і живою водою, і живим птахом і кедровим деревом, і ісопом і червленою ниткою;","і пустить живого птаха поза містом у поле й очистить дім, і буде чистий.","Ось закон про всяку виразку прокази і про паршивість,","і про проказу на одязі і на домі, і про пухлини, і про лишаї, і про плями, —","щоб указати, коли це нечисте і коли чисте. Ось закон про проказу."],"x":{"2":"50.8.2-3|51.1.44|52.5.14|52.17.14","4":"3.19.6|75.9.19|1.12.22","7":"2.4.6|2.8.11","8":"3.8.7|25.50.9|56.1.2","12":"1.29.24","13":"2.7.7","14":"2.8.23","16":"2.16.14","22":"2.12.8|2.15.14","25":"2.8.24","35":"2.13.2","44":"2.13.51","46":"2.11.24","51":"2.4.6|2.8.11","54":"2.16.16:33"}},{"v":["І сказав Господь Мойсеєві й Аарону, говорячи:","оголосіть синам Ізраїлевим і скажіть їм: якщо у кого буде теча з тіла його, то від течі своєї він нечистий.","І ось [закон] про нечистоту його від течі його: коли тече з тіла його теча його, і коли затримується в тілі його теча його, це нечистота його;","усяка постіль, на якій ляже той, хто має течу, нечиста, і всяка річ, на яку сяде [той, хто має течу сімені], нечиста;","і хто доторкнеться до постелі його, той повинен вимити одежу свою й омитися водою і нечистим буде до вечора;","хто сяде на будь-яку річ, на якій сидів той, хто має течу, той повинен вимити одежу свою й омитися водою і нечистий буде до вечора;","і хто доторкнеться до тіла того, хто має течу, той повинен вимити одежу свою й омитися водою і нечистий буде до вечора;","якщо той, хто має течу, плюне на чистого, то цей повинен вимити одежу свою й омитися водою, і нечистий буде до вечора;","і всякий візок, в якому їхав той, хто має течу, нечистий [буде до вечора];","і всякий, хто доторкнеться до чого-небудь, що було під ним, нечистий буде до вечора; і хто понесе це, повинен вимити одежу свою й омитися водою, і нечистий буде до вечора;","і всякий, до кого доторкнеться той, хто має течу, не омивши рук своїх водою, повинен вимити одежу свою й омитися водою, і нечистий буде до вечора;","глиняну посудину, до якої доторкнеться той, хто має течу, слід розбити, а всяку дерев’яну посудину треба вимити водою [і буде чистою].","А коли той, хто має течу, звільниться від течі своєї, тоді повинен він відрахувати собі сім днів для очищення свого і вимити одежу свою, й омити тіло своє живою водою, і буде чистий;","і у восьмий день візьме він собі двох горлиць або двох молодих голубів, і прийде перед лице Господнє до входу в скинію зібрання, і віддасть їх священикові;","і принесе священик з цих птахів одного в жертву за гріх, а іншого у всепалення, і очистить його священик перед Господом від течі його.","Якщо в кого трапиться виливання сімені, то він повинен омити водою все тіло своє, і нечистий буде до вечора;","і всякий одяг і всяка шкіра, на яку потрапить сíм’я, повинні бути вимиті водою, і нечистими будуть до вечора;","якщо чоловік ляже з жінкою і буде в нього виливання сімені, то вони повинні омитися водою, і нечисті будуть до вечора.","Якщо жінка має течу крови, що тече з тіла її, то вона повинна сидіти сім днів під час очищення свого, і всякий, хто доторкнеться до неї, нечистий буде до вечора;","і все, на чому вона ляже під час очищення свого, нечисте; і все, на чому сяде, нечисте;","і всякий, хто доторкнеться до постелі її, повинен вимити одежу свою й омитися водою, і нечистий буде до вечора;","і всякий, хто доторкнеться до якої-небудь речі, на якій вона сиділа, повинен вимити одежу свою й омитися водою, і нечистий буде до вечора;","і якщо хто доторкнеться до чого-небудь на постелі або на тій речі, на якій вона сиділа, нечистий буде до вечора;","якщо переспить з нею чоловік, то нечистота її буде на ньому; він нечистий буде сім днів, і всяка постіль, на якій він ляже, буде нечиста.","Якщо в жінки тече кров багато днів не під час очищення її, або якщо вона має течу довше звичайного очищення її, то весь час витікання нечистоти її, подібно як упродовж очищення свого, вона нечиста;","усяка постіль, на якій вона ляже в усі дні очищення свого, буде нечиста, подібно як постіль упродовж очищення її; і всяка річ, на яку вона сяде, буде нечиста, як нечисте це під час очищення її;","і всякий, хто доторкнеться до них, буде нечистий, і повинен вимити одежу свою й омитися водою, і нечистий буде до вечора.","А коли вона звільниться від течі своєї, тоді повинна відрахувати собі сім днів, і потім буде чиста;","у восьмий день візьме вона собі двох горлиць або двох молодих голубів і принесе їх до священика до входу у скинію зібрання;","і принесе священик одного з птахів у жертву за гріх, а іншого у всепалення, і очистить її священик перед Господом від течі нечистоти її.","Так охороняйте синів Ізраїлевих від нечистоти їх, щоб вони не померли в нечистоті своїй, оскверняючи оселю Мою, яка серед них:","ось закон про того, хто має течу, і про того, у кого трапиться виливання сімені, що робить його нечистим,","і про ту, що страждає очищенням своїм, і про тих, хто має витікання, чоловіка або жінку, і про чоловіка, який переспить з нечистою."],"x":{"2":"2.22.4|9.3.29","5":"2.11.24","12":"2.6.28","13":"3.19.11","14":"2.12.8","19":"2.18.19","24":"2.18.19|36.18.6","25":"50.9.20","29":"2.12.8|2.14.22"}},{"v":["І говорив Господь Мойсеєві після смерти двох синів Ааронових, коли вони, приступивши [з чужим огнем] перед лице Господнє, померли,","і сказав Господь Мойсеєві: скажи Аарону, братові твоєму, щоб він не в усякий час входив у святилище за завісу перед кришку [очистилище], що на ковчезі [одкровення], щоб йому не померти, бо над кришкою Я буду являтися у хмарі.","Ось з чим повинен входити Аарон у святилище: з тельцем у жертву за гріх і з бараном у всепалення;","священний лляний хітон повинен він надівати, нижній одяг лляний нехай буде на тілі його, і лляним поясом нехай підперезується, і лляний кидар одягає: це священні одежі; і нехай омиває він тіло своє водою і зодягає їх;","і від громади синів Ізраїлевих нехай візьме [з отари кіз] двох козлів у жертву за гріх і одного барана у всепалення.","І принесе Аарон тельця в жертву за гріх за себе й очистить себе і дім свій.","І візьме двох козлів і поставить їх перед лицем Господнім при вході до скинії зібрання;","і кине Аарон щодо обох козлів жереби: один жереб для Господа, а інший жереб для відпущення;","і приведе Аарон козла, на якого випав жереб для Господа, і принесе його в жертву за гріх,","а козла, на якого випав жереб для відпущення, поставить живого перед Господом, щоб звершити над ним очищення і відіслати його в пустелю для відпущення [і щоб він поніс на собі їхні беззаконня в землю непрохідну].","І приведе Аарон тельця в жертву за гріх за себе, і очистить себе і дім свій, і заколе тельця в жертву за гріх за себе;","і візьме розпаленого вугілля повну кадильницю з жертовника, який перед лицем Господнім, і запашного дрібно стовченого куріння повну жменю, і внесе за завісу;","і покладе куріння на вогонь перед лицем Господнім, і хмара куріння покриє кришку, що над ковчегом одкровення, щоб йому не померти;","і візьме крови тельця і покропить перстом своїм кришку спереду і перед кришкою, сім разів покропить кров’ю з перста свого.","І заколе козла в жертву за гріх за народ, і внесе кров його за завісу, і зробить з кров’ю його те саме, що робив із кров’ю тельця, і покропить нею кришку і перед кришкою, —","і очистить святилище від нечистот синів Ізраїлевих і від злочинів їхніх, в усіх гріхах їхніх. Так повинен вчинити він і зі скинією зібрання, що знаходиться в них, серед нечистот їхніх.","Жодна людина не повинна бути в скинії зібрання, коли входить він для очищення святилища, до самого виходу його. І так очистить він себе, дім свій і всю громаду Ізраїлеву.","І вийде він до жертовника, який перед лицем Господнім, і очистить його, і візьме крови тельця і крови козла, і покладе на роги жертовника з усіх боків,","і покропить його кров’ю з перста свого сім разів, і очистить його, і освятить його від нечистот синів Ізраїлевих.","І звершивши очищення святилища, скинії зібрання і жертовника [і очистивши священиків], приведе він живого козла,","і покладе Аарон обидві руки свої на голову живого козла, і сповідає над ним усі беззаконня синів Ізраїлевих і всі злочини їхні і всі гріхи їхні, і покладе їх на голову козла, і відішле з призначеною людиною в пустелю:","і понесе козел на собі всі беззаконня їхні у землю непрохідну, і пустить він козла в пустелю.","І ввійде Аарон у скинію зібрання і зніме лляний одяг, який одягав, входячи у святилище, і залишить його там,","і омиє тіло своє водою на святому місці, і зодягне одежу свою, і вийде і звершить всепалення за себе і всепалення за народ, і очистить себе, [дім свій] і народ [і священиків];","а жиром жертви за гріх покадить на жертовнику.","І той, хто відводив козла для відпущення, повинен вимити одежу свою, омити тіло своє водою, і потім може ввійти у стан.","А тельця за гріх і козла за гріх, кров яких внесена була для очищення святилища, нехай винесуть геть зі стану і спалять на вогні шкури їх і м’ясо їх і нечистоту їх;","хто спалить їх, той повинен вимити одежу свою й омити тіло своє водою, і після того може ввійти у стан.","І нехай буде це для вас вічною постановою: у сьомий місяць, в десятий [день] місяця смиряйте душі ваші і ніякої справи не робіть, ні тубілець, ні прибулець, що оселився між вами,","тому що в цей день очищають вас, щоб зробити вас чистими від усіх гріхів ваших, щоб ви були чисті перед лицем Господнім;","це субота спокою для вас, смиряйте душі ваші: це постанова вічна.","Очищати ж повинен священик, який помазаний і який освячений, щоб священнодіяти йому замість батька свого: і зодягне він лляну одежу, одежу священну,","і очистить Святе Святих і скинію зібрання, і жертовник очистить, і священиків і весь народ громади очистить.","І нехай буде це для вас вічною постановою: очищати синів Ізраїлевих від усіх гріхів їхніх один раз на рік. І зробив він так, як повелів Господь Мойсеєві."],"x":{"1":"2.10.1-2|3.3.4","2":"1.30.10|75.9.7:13","5":"3.29.11","6":"3.1.49","11":"75.7.27","12":"2.6.12|1.30.34","14":"75.9.13|75.10.4|2.4.6:17","16":"75.9.2","17":"52.1.10","19":"2.14.7","22":"2.16.10","27":"75.13.11","29":"2.23.27","34":"1.30.10|2.16.2|75.9.7"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси Аарону і синам його і всім синам Ізраїлевим і скажи їм: ось що повеліває Господь:","якщо хто з дому Ізраїлевого [або з прибульців, що приєдналися до вас] заколе тельця або вівцю чи козу в стані, або якщо хто заколе поза станом","і не приведе до входу скинії зібрання, [щоб принести у всепалення або в жертву за спасіння, угодну Господу, у приємні пахощі, і якщо хто заколе поза станом і до входу в скинію зібрання не принесе,] щоб представити в жертву Господу перед оселею Господньою, то людині тій буде поставлена кров: він пролив кров, і знищиться людина та з народу свого;","це для того, щоб приводили сини Ізраїлеві жертви свої, які вони заколюють на полі, щоб приводили їх перед Господом до входу в скинію зібрання, до священика, і заколювали їх Господу в жертви мирні;","і покропить священик кров’ю жертовник Господній при вході у скинію зібрання і спалить жир у приємні пахощі Господу,","щоб вони надалі не приносили жертв своїм ідолам, за якими блудно ходять вони. Це нехай буде для них постановою вічною в роди їх.","Ще скажи їм: якщо хто з дому Ізраїлевого і з прибульців, які живуть між вами, приносить всепалення або жертву","і не приведе до входу у скинію зібрання, щоб принести її Господу, то знищиться людина та з народу свого.","Якщо хто з дому Ізраїлевого і з прибульців, які живуть між вами, буде їсти яку-небудь кров, то зверну лице Моє на душу того, хто буде їсти кров, і знищу її з народу її,","тому що душа тіла в крові, і Я призначив її вам для жертовника, щоб очищати душі ваші, бо кров ця душу очищає;","тому Я і сказав синам Ізраїлевим: жодна душа з вас не повинна їсти крови, і прибулець, що живе між вами, не повинен їсти крови.","Якщо хто із синів Ізраїлевих і з прибульців, що живуть між вами, на ловитві упіймає звіра або птаха, якого можна їсти, то він повинен дати витекти крові її і покрити її землею,","тому що душа всякого тіла є кров його, вона душа його; тому Я сказав синам Ізраїлевим: не їжте крови ні з якого тіла, тому що душа всякого тіла є кров його: усякий, хто буде їсти її, знищиться.","І всякий, хто буде їсти мертвечину або роздерте звіром, тубілець або прибулець, повинен вимити одежу свою й омитися водою, і нечистий буде до вечора, а потім буде чистий;","якщо ж не вимиє [одягу свого] і не обмиє тіла свого, то понесе на собі беззаконня своє."],"x":{"2":"2.6.25","4":"0.17.14","6":"75.13.11|1.29.18","7":"2.20.3|4.32.17","9":"5.22.16","10":"0.9.4|4.12.23|25.33.17","11":"4.12.23|68.1.20|75.9.13","14":"0.9.4|2.3.17","15":"2.11.40|4.14.21|36.44.31"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: Я Господь, Бог ваш.","За ділами землі Єгипетської, у якій ви жили, не чиніть, і за ділами землі Ханаанської, у яку Я веду вас, не чиніть, і за встановленнями їх не ходіть:","Мої закони виконуйте і Моїх постанов дотримуйтеся, чинячи за ними. Я Господь, Бог ваш.","Додержуйтесь постанов Моїх і законів Моїх, виконуючи які людина буде живою. Я Господь [Бог ваш].","Ніхто ні до якої родички за плоттю не повинен наближатися з тим, щоб відкрити наготу. Я Господь.","Наготи батька твого і наготи матері твоєї не відкривай: вона мати твоя, не відкривай наготи її.","Наготи дружини батька твого не відкривай: це нагота батька твого.","Наготи сестри твоєї, дочки батька твого або дочки матері твоєї, народженої в домі або поза домом, не відкривай наготи їх.","Наготи дочки сина твого або дочки дочки твоєї, не відкривай наготи їх, тому що вони твоя нагота.","Наготи дочки дружини батька твого, яка народилася від батька твого, вона сестра твоя [за батьком], не відкривай наготи її.","Наготи сестри батька твого не відкривай, вона єдинокровна батькові твоєму.","Наготи сестри матері твоєї не відкривай, бо вона єдинокровна матері твоїй.","Наготи брата батька твого не відкривай і до дружини його не наближайся: вона тітка твоя.","Наготи невістки твоєї не відкривай: вона дружина сина твого, не відкривай наготи її.","Наготи дружини брата твого не відкривай, це нагота брата твого.","Наготи дружини і дочки її не відкривай; дочки сина її і дочки дочки її не бери, щоб відкрити наготу їхню, вони єдинокровні її; це беззаконня.","Не бери дружини разом із сестрою її, щоб зробити її суперницею, щоб відкрити наготу її при ній, за життя її.","І до дружини під час очищення нечистот її не наближайся, щоб відкрити наготу її.","І з дружиною ближнього твого не лягай, щоб вилити сíм’я і осквернитися з нею.","Із дітей твоїх не віддавай на служіння Молоху і не знечещуй імені Бога твого. Я Господь.","Не лягай з чоловіком як з жінкою: це мерзенність.","І ні з якою худобою не лягай, щоб вилити [сíм’я] і осквернитися від цього; і жінка не повинна ставати перед худобою для злучення з нею: це мерзенно.","Не опоганюйте себе нічим цим, тому що всім цим опоганили себе народи, яких Я проганяю від вас:","і опоганилася земля, і Я споглянув на беззаконня її, і звергла з себе земля тих, що жили на ній.","А ви дотримуйтеся постанов Моїх і законів Моїх і не робіть усіх цих гидот, ні тубілець, ні прибулець, що живе між вами,","тому що всі ці мерзоти робили люди цієї землі, що перед вами, і опоганилася земля;","щоб і вас не звергла із себе земля, коли ви станете опоганювати її, як вона звергла народи, що були раніше вас;","бо якщо хто буде робити усі ці мерзоти, то душі, які роблять це, знищені будуть з народу свого.","Отже, дотримуйтеся повелінь Моїх, щоб не чинити за гидотними звичаями, за якими чинили раніше за вас, і щоб не опоганюватися ними. Я Господь, Бог ваш."],"x":{"2":"2.11.44","4":"50.15.3","5":"36.20.11|17.9.29|62.10.5|65.3.12","6":"9.16.22","7":"0.9.22-23|0.19.32|36.22.10","8":"4.27.20|9.16.22|36.22.10","9":"4.27.22|9.13.12|36.22.11","12":"2.20.19","14":"2.20.20","15":"0.38.16|4.27.23|36.22.11","16":"2.20.21|50.14.4|51.6.18","17":"2.20.14","19":"2.15.19","20":"2.20.10","21":"2.20.2|11.23.10","22":"62.1.27|63.6.9","23":"1.22.19","24":"2.20.23|11.17.15","25":"31.26.21","28":"2.20.22","30":"2.19.37|2.20.8"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси всій громаді синів Ізраїлевих і скажи їм: будьте святими, бо святий Я Господь, Бог ваш.","Бійтеся кожен матері своєї і батька свого і суботи Мої зберігайте. Я Господь, Бог ваш.","Не звертайтеся до ідолів і богів відлитих не робіть собі. Я Господь, Бог ваш.","Коли будете приносити Господу жертву мирну, то приносьте її, щоб придбати собі благовоління:","у день жертвоприношення вашого і на другий день слід з’їсти її, а те, що залишилося до третього дня, треба спалити на вогні;","якщо ж хто стане їсти її на третій день, це мерзенно, це не буде благоприємне;","хто стане їсти її, той понесе на собі гріх, бо він осквернив святиню Господню, і знищиться душа та з народу свого.","Коли будете жати жнива на землі вашій, не дожинай до краю поля твого, і залишків від жнив твоїх не підбирай,","і виноградника твого не оббирай дочиста, і ягід, що попа́дали у винограднику, не підбирай; залиш це бідному і прибульцеві. Я Господь, Бог ваш.","Не крадіть, не говоріть неправди і не обманюйте одне одного.","Не клянись ім’ям Моїм у неправді, і не знечещуй імені Бога твого. Я Господь [Бог ваш].","Не кривди ближнього твого і не грабуй. Плата найманцеві не повинна залишатися в тебе до ранку.","Не лихослов глухого і перед сліпим не клади нічого, щоб не спіткнувся він; бійся [Господа] Бога твого. Я Господь [Бог ваш].","Не чиніть неправди на суді; не будь упереджений до жебрака і не догоджай лицю великого; за правдою суди ближнього твого.","Не ходи пліткарем у народі твоєму і не повставай на життя ближнього твого. Я Господь [Бог ваш].","Не ворогуй на брата твого у серці твоєму; викрий ближнього твого, і не понесеш за нього гріха.","Не мстися і не май злоби на синів народу твого, але люби ближнього твого, як самого себе. Я Господь [Бог ваш].","Уставів Моїх додержуйте; худоби твоєї не зводь з іншою породою; поля твого не засівай двома родами насіння; в одяг з різнорідних ниток, з вовни і льону, не одягайся.","Якщо хто переспить з жінкою, а вона раба, заручена з чоловіком, але ще не викуплена, або свобода ще не дана їй, то слід покарати їх, але не смертю, тому що вона невільна:","нехай приведе він Господу до входу в скинію зібрання жертву за провину, барана в жертву за провину свою;","і очистить його священик бараном за провину перед Господом від гріха, яким він згрішив, і прощений буде йому гріх, яким він згрішив.","Коли прийдете в землю, [яку Господь Бог дасть вам,] і посадите яке-небудь плодове дерево, то плоди його вважайте за необрізані: три роки слід вважати їх за необрізані, не слід їсти їх;","а на четвертий рік усі плоди його повинні бути посвячені для свят Господніх;","на п’ятий же рік ви можете їсти плоди його і збирати собі всі здобутки його. Я Господь, Бог ваш.","Не їжте з кров’ю; не ворожіть і не гадайте.","Не стрижіть голови вашої навкруги, і не псуй краю бороди твоєї.","Заради померлого не робіть нарізів на тілі вашому і не наколюйте на собі письмен. Я Господь [Бог ваш].","Не оскверняй дочки твоєї, допускаючи її до блуду, щоб не блудодіяла земля і не наповнилася земля розпустою.","Суботи Мої зберігайте і святилище Моє шануйте. Я Господь.","Не звертайтеся до тих, хто викликає мертвих, і до чарівників не ходіть, і не доводьте себе до опоганення від них. Я Господь, Бог ваш.","Перед лицем сивого вставай і шануй лице старця, і бійся [Господа] Бога твого. Я Господь [Бог ваш].","Коли оселиться прибулець у землі вашій, не пригноблюйте його:","прибулець, який оселився у вас, нехай буде для вас те саме, що тубілець ваш; люби його, як себе; тому що і ви були прибульцями в землі Єгипетській. Я Господь, Бог ваш.","Не чиніть неправди в суді, у мірі, у вазі й у вимірі:","нехай будуть у вас терези правильні, гирі правильні, ефа правильна і гин правильний. Я Господь, Бог ваш, Який вивів вас із землі Єгипетської.","Дотримуйтесь усіх уставів Моїх і всіх законів Моїх і виконуйте їх. Я Господь [Бог ваш]."],"x":{"2":"2.11.44|56.1.15-16","3":"1.20.12|30.3.6-9|1.20.8","4":"1.20.4","5":"2.3.1","6":"2.7.16-17","7":"2.7.18","8":"0.17.14","9":"2.23.22|4.24.19","11":"1.20.15","12":"1.20.7|4.5.11|50.5.33","13":"30.10.6|4.24.14|18.4.14|30.34.22","15":"4.1.17|4.16.19|30.42.1|26.24.23|55.2.1","17":"58.2.11|50.18.15|52.17.3","18":"50.5.43|50.22.39|51.12.31|62.13.9|65.5.14|55.2.8","22":"2.4.26|2.5.13","23":"4.20.6","24":"17.10.35","26":"4.18.10|11.21.6","28":"4.14.1|10.18.28","29":"30.26.13","30":"2.23.2","31":"2.20.6|4.18.11|31.8.19","32":"30.8.7","33":"1.22.21","36":"4.25.13-15|26.11.1|36.45.10","37":"2.18.30|4.7.12"}},{"v":["І сказав Господь Мойсеєві, говорячи:","скажи це синам Ізраїлевим: хто із синів Ізраїлевих і з прибульців, що живуть між ізраїльтянами, дасть дітей своїх Молоху, той нехай буде відданий на смерть: народ землі нехай поб’є його камінням;","і Я зверну лице Моє на людину ту і знищу її з народу її за те, що вона дала дітей своїх Молохові, щоб осквернити святилище Моє і зганьбити святе ім’я Моє;","і якщо народ землі не зверне очей своїх на людину ту, коли вона дасть дітей своїх Молохові, і не умертвить її,","то Я зверну лице Моє на людину ту і на рід її і винищу його з народу його, і всіх, хто блудить слідами її, щоб ходити блудно услід Молохові.","І якщо яка душа звернеться до тих, хто викликає мертвих і до чаклунів, щоб блудно ходити услід їм, то Я зверну лице Моє на ту душу і знищу її з народу її.","Освячуйте себе і будьте святими, бо Я Господь, Бог ваш, [святий].","Дотримуйтеся постанов Моїх і виконуйте їх, бо Я Господь, що освячує вас.","Хто буде лихословити батька свого або матір свою, той нехай буде відданий на смерть; батька свого і матір свою він лихословив: кров його на ньому.","Якщо хто буде перелюбствувати з жінкою одруженою, якщо хто буде перелюбствувати з дружиною ближнього свого, — нехай будуть віддані на смерть і перелюбник і перелюбниця.","Хто ляже з дружиною батька свого, той відкрив наготу батька свого: обоє вони нехай будуть віддані на смерть, кров їхня на них.","Якщо хто ляже з невісткою своєю, то обоє вони нехай будуть віддані на смерть: мерзотність зробили вони, кров їхня на них.","Якщо хто ляже з чоловіком, як з жінкою, то обоє вони зробили мерзотність: нехай будуть віддані на смерть, кров їхня на них.","Якщо хто візьме собі дружину і матір її: це беззаконня; на вогні слід спалити його і їх, щоб не було беззаконня між вами.","Хто змішається з худобою, того віддати на смерть, і худобу вбийте.","Якщо жінка піде до якої-небудь худоби, щоб злучитися з нею, то убий жінку і худобу: нехай будуть вони віддані на смерть, кров їхня на них.","Якщо хто візьме сестру свою, дочку батька свого або дочку матері своєї, і побачить наготу її, і вона побачить наготу його: це сором, нехай будуть вони знищені перед очима синів народу свого; він відкрив наготу сестри своєї: гріх свій понесе він.","Якщо хто ляже з дружиною під час хвороби кровоочищення і відкриє наготу її, то він відкрив течу її, і вона відкрила течу крови своєї: обоє вони нехай будуть знищені з народу свого.","Наготи сестри матері твоєї і сестри батька твого не відкривай, бо такий оголює плоть свою: гріх свій понесуть вони.","Хто ляже з тіткою своєю, той відкрив наготу дядька свого; гріх свій понесуть вони, бездітними помруть.","Якщо хто візьме дружину брата свого: це огидно; він відкрив наготу брата свого, бездітними будуть вони.","Дотримуйтесь усіх уставів Моїх і всіх законів Моїх і виконуйте їх, — і не звергне вас із себе земля, в яку Я веду вас жити.","Не чиніть за звичаями народу, який Я проганяю від вас; тому що вони все це робили, і Я обурився на них,","і сказав Я вам: ви володарюйте землею їхньою, і вам віддаю у спадщину землю, в якій тече молоко і мед. Я Господь, Бог ваш, Який відділив вас від усіх народів.","Відрізняйте худобу чисту від нечистої і птаха чистого від нечистого і не оскверняйте душ ваших худобою і птахами і всім, що плазує по землі, що визначив Я, як нечисте.","Будьте переді Мною святі, бо Я святий Господь [Бог ваш], і Я відокремив вас від народів, щоб ви були Мої.","Чоловік чи жінка, якщо будуть вони викликати мертвих або ворожити, нехай будуть віддані на смерть: камінням слід побити їх, кров їхня на них."],"x":{"2":"2.18.21|11.23.10","6":"2.19.31","7":"2.11.44|2.19.2|56.1.15-16","9":"1.21.17|26.20.20|50.15.4|51.7.10","10":"4.22.22|53.8.4-5","11":"0.35.22","12":"0.38.16|63.6.9","13":"2.18.22|62.1.27|63.6.9","14":"2.18.17","15":"2.18.23","17":"2.18.9","18":"2.15.24|36.18.6","19":"2.18.12","20":"38.9.11-12","21":"2.18.16|51.6.18","22":"2.18.28:30","23":"2.18.24|4.9.5","24":"1.3.8|1.13.5","25":"4.14.4","26":"2.11.45|2.19.2|50.5.48","27":"4.18.11|8.28.7"}},{"v":["І сказав Господь Мойсеєві: оголоси священикам, синам Аароновим, і скажи їм: нехай не оскверняють себе дотиком до померлого з народу свого;","тільки до близького родича свого, до матері своєї і до батька свого, до сина свого і дочки своєї, до брата свого","і до сестри своєї, дівчини, що живе при ньому і не була заміжня, можна йому доторкатися, не оскверняючи себе;","і доторканням до кого б то не було в народі своєму не повинен він оскверняти себе, щоб не стати нечистим.","Вони не повинні голити голови своєї і підстригати краї бороди своєї і робити нарізи на тілі своєму.","Вони повинні бути святими Богові своєму і не повинні нечестити імені Бога свого, тому що вони приносять жертви Господу, хліб Богу своєму, і тому повинні бути святими.","Вони не повинні брати за себе блудницю і знечещену, не повинні брати і жінку, вигнану чоловіком своїм, бо вони святі [Господу] Богу своєму.","Святи́ його, бо він приносить хліб [Господу] Богу твоєму: нехай буде він у тебе святим, бо святий Я Господь, Який освячує вас.","Якщо дочка священика осквернить себе блудодіянням, то вона нечестить батька свого; вогнем слід спалити її.","Великий же священик з братів своїх, на голову якого полито єлей помазання, і який освячений, щоб облачатися у священні одежі, не повинен оголювати голови своєї і роздирати одежі своєї;","і ні до якого померлого не повинен він приступати: навіть дотиком до померлого батька свого і матері своєї він не повинен оскверняти себе.","І від святилища він не повинен відходити і нечестити святилище Бога свого, бо освячення єлеєм помазання Бога його на ньому. Я Господь.","За дружину він повинен брати дівчину [з народу свого];","вдову, або вигнану, або знечещену, [або] блудницю, не повинен він брати, але дівчину з народу свого повинен він брати за дружину;","він не повинен ганьбити сімені свого в народі своєму, бо Я Господь [Бог], що освячує його.","І сказав Господь Мойсеєві, говорячи:","скажи Аарону: ніхто з сімені твого в усі роди їх, у якого на тілі буде вада, не повинен приступати, щоб приносити хліб Богу своєму;","ніхто, у кого на тілі є вада, не повинен приступати, ні сліпий, ні кульгавий, ні потворний,","ні такий, у якого переламана нога або переламана рука,","ні горбатий, ні із сухим органом, ні з більмом на оці, ні коростявий, ні паршивий, ні з пошкодженими ядрами;","жоден чоловік з сімені Аарона священика, у якого на тілі є вада, не повинен приступати, щоб приносити жертви Господу; вада на ньому, тому не повинен він приступати, щоб приносити хліб Богу своєму;","хліб Бога свого з великих святинь і зі святинь він може їсти;","але до завіси не повинен він приходити і до жертовника не повинен приступати, тому що вада на ньому: не повинен він нечестити святилища Мого, бо Я Господь, що освячує їх.","І оголосив це Мойсей Аарону і синам його і всім синам Ізраїлевим."],"x":{"1":"36.44.25","2":"3.6.7","5":"2.19.27|4.14.1|36.44.20","7":"36.44.22|66.5.27","8":"2.11.44","10":"1.28.41|2.10.6","11":"3.6.7|3.9.6","12":"2.10.7|1.28.38","13":"36.44.22","17":"71.3.2|73.1.7","18":"71.6.14|57.3.14","23":"2.22.9"}},{"v":["І сказав Господь Мойсеєві, говорячи:","скажи Аарону і синам його, щоб вони обережно поводилися зі святинями синів Ізраїлевих і не ганьбили святого імені Мого в тому, що вони посвячують Мені. Я Господь.","Скажи їм: якщо хто з усіх нащадків ваших в роди ваші, маючи на собі нечистоту, приступить до святинь, які посвячують сини Ізраїлеві Господу, то знищиться душа та від лиця Мого. Я Господь [Бог ваш].","Хто із сімені Ааронового прокажений, або має течу, той не повинен їсти святинь, поки не очиститься; і хто доторкнеться до чого-небудь нечистого від мертвого, або в кого трапиться вилив сімені,","або хто доторкнеться до якого-небудь гада, від якого він стане нечистим, або до людини, від якої він стане нечистим якою б то не було нечистотою, —","той, хто доторкнеться до цього, нечистий буде до вечора і не повинен їсти святинь, раніше ніж омиє тіло своє водою;","але коли зайде сонце і він очиститься, тоді може він їсти святині, бо це його їжа.","Мертвечини і роздертого звіром він не повинен їсти, щоб не осквернитися цим. Я Господь.","Нехай дотримуються вони повелінь Моїх, щоб не понести на собі гріха і не померти в ньому, коли порушать це. Я Господь [Бог], що освячує їх.","Ніхто сторонній не повинен їсти святині; хто оселився у священика і найманець не повинен їсти святині;","якщо ж священик купить собі чоловіка за срібло, то цей може їсти її; також і домашні його можуть їсти хліб його.","Якщо дочка священика вийде заміж за стороннього, то вона не повинна їсти принесених святинь;","коли ж дочка священика буде вдовою, або розведеною, і дітей немає в неї, і повернеться в дім батька свого, як була в молодості своїй, тоді вона може їсти хліб батька свого; а сторонній ніхто не повинен їсти його.","Хто помилково з’їсть що-небудь зі святині, той повинен віддати священику святиню і докласти до неї п’яту її частку.","Священики самі не повинні ганьбити святині синів Ізраїлевих, які вони приносять Господу,","і не повинні накликати на себе провину в злочині, коли будуть їсти святині свої, бо Я Господь, що освячує їх.","І сказав Господь Мойсеєві, говорячи:","оголоси Аарону і синам його і всім синам Ізраїлевим і скажи їм: якщо хто з дому Ізраїлевого, або із прибульців, [що оселилися] між ізраїльтянами, чи за якоюсь обітницею, або з ревности приносить жертву свою, яку приносять Господу у всепалення,","то, щоб цим придбати благовоління від Бога, жертва повинна бути без вад, чоловічої статі, з великої худоби, з овець і з кіз;","ніякої тварини, на якій є вада, не приносьте [Господу], бо це не придбає вам благовоління.","І якщо хто приносить мирну жертву Господу, виконуючи обітницю, або з ревности, [або у свята ваші,] з великої худоби або з дрібної, то жертва повинна бути без вад, щоб бути угодною Богу: ніякої вади не повинно бути на ній;","тварини сліпої, або пошкодженої, або потворної, або хворої, або коростявої, або паршивої, таких не приносьте Господу і в жертву не давайте їх на жертовник Господній;","тельця й агнця з кінцівками, надмірно довгими або короткими, у жертву ревности принести можеш; а якщо за обітницею, то це не угодно буде Богу;","тварину, у якої ядра розчавлені, розбиті, відірвані або вирізані, не приносьте Господу й у землі вашій не робіть цього,","і з рук іноземців не приносьте всіх таких тварин у дар Богу вашому, бо на них пошкодження, порок на них: не придбають вони вам благовоління.","І сказав Господь Мойсеєві, говорячи:","коли народиться теля, або ягня, або козеня, то сім днів воно має пробути при матері своїй, а від восьмого дня і далі буде благовгодне для приношення в жертву Господу;","але ні корови, ні вівці не заколюйте в один день з породженням її.","Якщо приносите Господу жертву подяки, то приносьте її так, щоб вона придбала вам благовоління;","у той самий день слід з’їсти її, не залишайте від неї до ранку. Я Господь.","І дотримуйтеся заповідей Моїх і виконуйте їх. Я Господь.","Не ганьбіть святого імені Мого, щоб Я був святим серед синів Ізраїлевих. Я Господь, Який освячує вас,","Який вивів вас із землі Єгипетської, щоб бути вашим Богом. Я Господь."],"x":{"2":"2.6.25|3.6.23","4":"2.15.2:16|13.30.18","5":"2.11.29","6":"2.11.24|57.3.14","8":"1.22.31|36.44.31","9":"2.5.1","10":"1.12.44","13":"2.10.14","14":"2.5.15","16":"2.21.8","18":"25.49.14","20":"4.15.21|30.35.11","21":"2.7.16","22":"49.1.8:13","27":"1.22.30","28":"4.22.6","29":"2.7.12","30":"2.7.15-16","31":"2.18.30","32":"2.10.3|2.21.8","33":"1.13.3"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм про свята Господні, в які слід скликати священне зібрання. Ось свята Мої:","шість днів можна робити справи, а в сьомий день субота спокою, священне зібрання; ніякої справи не робіть; це субота Господня у всіх оселях ваших.","Ось свята Господні, священні зібрання, які ви повинні скликати у свій час:","у перший місяць, у чотирнадцятий [день] місяця увечері Пасха Господня;","і в п’ятнадцятий день того самого місяця свято опрісноків Господу; сім днів їжте опрісноки;","у перший день нехай буде у вас священне зібрання; ніякої роботи не виконуйте;","і протягом семи днів приносьте жертви Господу; у сьомий день також священне зібрання; ніякої роботи не виконуйте.","І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли прийдете в землю, яку Я даю вам, і будете жати на ній жнива, то принесіть перший сніп жнив ваших до священика;","він піднесе цей сніп перед Господом, щоб вам придбати благовоління; на другий день свята піднесе його священик;","і в день возношення снопа принесіть у всепалення Господу агнця однолітнього, без вад,","і з ним хлібного приношення дві десятих частини ефи пшеничного борошна, змішаного з єлеєм, у жертву Господу, у приємні пахощі, й узливання до неї чверть гина вина;","ніякого нового хліба, ні сушених зерен, ні зерен сирих не їжте до того дня, в який принесете приношення Богу вашому: це вічна постанова в роди ваші у всіх оселях ваших.","Відрахуйте собі від першого дня після свята, від того дня, у який приносите сніп потрясання, сім повних тижнів,","до першого дня після сьомого тижня відрахуйте п’ятдесят днів, і тоді принесіть нове хлібне приношення Господу:","від осель ваших приносьте два хліби возношення, які повинні складатися з двох десятих частин ефи пшеничного борошна і повинні бути спечені кислі, як перший плід Господу;","разом із хлібами представте сім агнців без вад, однолітніх, і з великої худоби одного тельця і двох баранів [без вад]; нехай буде це у всепалення Господу, і хлібне приношення й узливання до них, у жертву, у приємні пахощі Господу.","Приготуйте також з отари кіз одного козла в жертву за гріх і двох однолітніх агнців у жертву мирну [разом із хлібом першого плоду];","священик повинен принести це, потрясаючи перед Господом, разом з хлібами потрясіння першого плоду і з двома агнцями, і це буде святинею Господу; священикові, [який приносить, це належить];","і скликайте народ у цей день, священне зібрання нехай буде у вас, ніякої роботи не виконуйте: це постанова вічна у всіх оселях ваших у роди ваші.","Коли будете жати жниво на землі вашій, не дожинай до краю поля твого, коли жнеш, і залишок від жаття твого не підбирай; бідному і прибульцеві залиш це. Я Господь, Бог ваш.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: у сьомий місяць, у перший [день] місяця нехай буде у вас спокій, свято труб, священне зібрання [нехай буде у вас];","ніякої роботи не виконуйте і приносьте жертву Господу.","І сказав Господь Мойсеєві, говорячи:","також у дев’ятий [день] сьомого місяця цього, день очищення, нехай буде у вас священне зібрання; смиряйте душі ваші і приносьте жертву Господу;","ніякої справи не робіть у день цей, бо це день очищення, щоб очистити вас перед лицем Господа, Бога вашого;","а всяка душа, що не смирить себе в цей день, знищиться з народу свого;","і якщо яка душа буде робити яку-небудь справу в день цей, Я знищу ту душу з народу її;","ніякої справи не робіть: ця постанова вічна в роди ваші, в усіх оселях ваших;","це для вас субота спокою, і смиряйте душі ваші, з вечора дев’ятого [дня] місяця; від вечора до вечора [десятого дня місяця] святкуйте суботу вашу.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим: з п’ятнадцятого дня того самого сьомого місяця свято кущів, сім днів Господу;","у перший день священне зібрання, ніякої роботи не виконуйте;","протягом семи днів приносьте жертву Господу; у восьмий день священне зібрання нехай буде у вас, і приносьте жертву Господу: це віддання свята, ніякої роботи не виконуйте.","Ось свята Господні, в які слід скликати священне зібрання, щоб приносити у жертву Господу всепалення, хлібне приношення, заколені жертви й узливання, кожне у свій день,","крім субот Господніх і крім дарів ваших, і крім всіх обітниць ваших і крім усього, що приноситься з ревности вашої, що ви даєте Господу.","А в п’ятнадцятий день сьомого місяця, коли ви збираєте врожай землі, святкуйте свято Господнє сім днів: у перший день спокій і у восьмий день спокій;","у перший день візьміть собі віття красивих дерев, віття пальмове і віття дерев широколистих і верб річкових, і веселіться перед Господом Богом вашим сім днів;","і святкуйте це свято Господнє сім днів у році: це постанова вічна в роди ваші; у сьомий місяць святкуйте його;","у кущах живіть сім днів; усякий тубілець ізраїльтянин повинен жити в кущах,","щоб знали роди ваші, що в кущах оселив Я синів Ізраїлевих, коли вивів їх із землі Єгипетської. Я Господь, Бог ваш.","І оголосив Мойсей синам Ізраїлевим про свята Господні."],"x":{"3":"1.20.9|4.5.13|75.4.4","5":"1.12.18|3.28.16","8":"4.16.8","10":"63.15.20|68.1.18","11":"1.29.28","13":"2.2.1|1.16.36","14":"2.2.14","15":"4.16.9|1.35.21","16":"3.28.26","21":"3.28.26","22":"2.19.9|4.24.19","24":"10.8.2|3.29.1|25.80.4","27":"2.16.29","32":"2.16.31","34":"53.7.2","36":"3.29.35|17.8.18|53.7.37","37":"3.29.2","40":"17.8.14-16|50.21.8|25.117.24"}},{"v":["І сказав Господь Мойсеєві, говорячи:","накажи синам Ізраїлевим, щоб вони принесли тобі єлею чистого, вичавленого, для освітлення, щоб постійно горів світильник;","ззовні завіси ковчега одкровення в скинії зібрання Аарон [і сини його] повинні ставити його перед Господом з вечора до ранку завжди: це вічна постанова в роди ваші;","на свічнику чистому повинні вони ставити світильник перед Господом завжди.","І візьми пшеничного борошна і спечи з нього дванадцять хлібів; у кожному хлібі повинні бути дві десятих ефи;","і поклади їх у два ряди, по шість у ряд, на чистому столі перед Господом;","і поклади на [кожен] ряд чистого ливану [і соли], і буде це при хлібі, у пам’ять, у жертву Господу;","у кожен день суботи постійно слід класти їх перед Господом від синів Ізраїлевих: це завіт вічний;","вони будуть належати Аарону і синам його, які будуть їсти їх на святому місці, бо це велика святиня для них із жертв Господніх: це постанова вічна.","І вийшов син однієї ізраїльтянки, що народилася від єгиптянина, до синів Ізраїлевих, і посварився у стані син ізраїльтянки з ізраїльтянином;","хулив син ізраїльтянки ім’я [Господнє] і лихословив. І привели його до Мойсея [ім’я ж матері його Саломиф, дочка Давриїна, з племені Данового];","і посадили його під варту, доки не буде оголошена їм воля Господня.","І сказав Господь Мойсеєві, говорячи:","виведи того, хто лихословив, геть зі стану, і всі, хто чув, нехай покладуть руки свої на голову його, і вся громада поб’є його камінням;","і синам Ізраїлевим скажи: хто буде лихословити Бога свого, той понесе гріх свій;","і хулитель ім’я Господнього повинен померти, камінням поб’є його вся громада: чи прибулець, чи тубілець стане хулити ім’я [Господнє], відданий буде на смерть.","Хто уб’є яку-небудь людину, той відданий буде на смерть.","Хто уб’є худобу, повинен заплатити за неї, худобу за худобу.","Хто зробить ушкодження на тілі ближнього свого, тому слід зробити те саме, що він зробив:","перелом за перелом, око за око, зуб за зуб; як він зробив ушкодження на тілі людини, так і йому треба зробити.","Хто уб’є худобу, повинен заплатити за неї; а хто уб’є людину, того треба віддати на смерть.","Один суд повинен бути у вас, як для прибульця, так і для тубільця; бо Я Господь, Бог ваш.","І сказав Мойсей синам Ізраїлевим; і вивели того, хто лихословив, геть зі стану, і побили його камінням, і зробили сини Ізраїлеві, як повелів Господь Мойсеєві."],"x":{"2":"1.27.20","3":"8.3.3|1.27.21","4":"1.25.31|53.1.7","5":"1.25.30|50.12.4|52.6.4","6":"1.25.30","7":"53.6.35","8":"50.12.5","9":"2.8.31|1.29.32|50.12.4|51.2.26","11":"4.28.58|50.9.3","12":"3.15.34","16":"1.20.7|50.26.65","17":"1.21.12","19":"1.21.24|4.19.21","20":"1.21.24|4.19.21|50.5.38","22":"1.12.49|4.1.16"}},{"v":["І сказав Господь Мойсею на горі Синаї, говорячи:","оголоси синам Ізраїлевим і скажи їм: коли прийдете в землю, яку Я даю вам, тоді земля повинна покоїтися в суботу Господню;","шість років засівай поле твоє і шість років обрізуй виноградник твій, і збирай плоди їх,","а в сьомий рік буде субота спокою землі, субота Господня: поля твого не засівай і виноградника твого не обрізуй;","що саме виросте на жниві твоєму, не пожинай, і грон з необрізаної лози твоєї не знімай; нехай буде це рік спокою землі;","і буде це упродовж суботи землі усім вам у їжу, тобі і рабові твоєму, і рабі твоїй, і найманцеві твоєму, і поселенцеві твоєму, що оселився у тебе;","і худобі твоїй і звірам, які на землі твоїй, нехай будуть усі плоди її в їжу.","І нарахуй собі сім суботніх років, сім разів по сім років, щоб було у тебе в семи суботніх роках сорок дев’ять років;","і засурми трубою в сьомий місяць, у десятий [день] місяця, у день очищення засурміть трубою по всій землі вашій;","і освятіть п’ятдесятий рік і оголосіть свободу на землі всім жителям її: нехай буде це у вас ювілей; і поверніться кожен у володіння своє, і кожен поверніться у своє плем’я.","П’ятдесятий рік нехай буде у вас ювілейний: не сійте і не жніть, що саме виросте на землі, і не знімайте ягід з необрізаної лози,","бо це ювілей: священним нехай буде він для вас; з поля їжте врожай його.","В ювілейний рік повертайтеся кожен у володіння своє.","Якщо будеш продавати що ближньому твоєму, або будеш купувати що у ближнього твого, не кривдьте одне одного;","за розрахунком років після ювілею ти повинен купувати у ближнього твого, і за розрахунком років прибутку він повинен продавати тобі;","якщо багато залишається років, збільши ціну; а якщо мало років залишається, зменши ціну, бо за відповідну кількість років жнив він продає тобі.","Не кривдьте одне одного; бійся Бога твого, бо Я Господь, Бог ваш.","Виконуйте постанови Мої, і зберігайте закони Мої і виконуйте їх, і будете жити спокійно на землі;","і буде земля давати плід свій, і будете їсти досита, і будете жити спокійно на ній.","Якщо скажете: що ж нам їсти в сьомий рік, коли ми не будемо ні сіяти, ні збирати врожаї наші?","Я пошлю благословення Моє на вас у шостий рік, і він принесе врожаю на три роки;","і будете сіяти у восьмий рік, але будете їсти врожаї старі до дев’ятого року; доки не вистигне врожай його, будете їсти старе.","Землю не слід продавати назавжди, бо Моя земля: ви прибульці і поселенці у Мене;","по всій землі володіння вашого дозволяйте викуп землі.","Якщо брат твій зубожіє і продасть від володіння свого, то прийде близький його родич і викупить продане братом його;","якщо ж нема кому за нього викупити, але сам він буде мати достаток і знайде, скільки потрібно на викуп,","то нехай він розрахує роки продажу свого і поверне залишок тому, кому він продав, і вступить знову у володіння своє;","якщо ж не знайде рука його, скільки потрібно повернути йому, то продане ним залишиться у руках покупця до ювілейного року, а в ювілейний рік відійде воно, і він знову вступить у володіння своє.","Якщо хто продасть житловий будинок у місті, огородженому стіною, то викупити його можна до закінчення року від продажу його: протягом року викупити його можна;","якщо ж не буде він викуплений до закінчення цілого року, то будинок, який у місті, що має стіну, залишиться назавжди у покупця його в роди його, і в ювілей не відійде від нього.","А будинки в селищах, навколо яких нема стіни, слід вважати нарівні з полем землі: викуповувати їх [завжди] можна, і в ювілей вони відходять.","А міста левитів, будинки в містах володіння їх, левитам завжди можна викуповувати;","а хто з левитів не викупить, то проданий будинок у місті володіння їх у ювілей відійде, бо будинки в містах левитських складають їхнє володіння серед синів Ізраїлевих;","і поля навколо міст їхніх продавати не можна, бо це вічне володіння їх.","Якщо брат твій зубожіє і прийде в занепад у тебе, то підтримай його, чи прибулець він, або поселенець, щоб він жив з тобою;","не бери від нього лихви і прибутку і бійся Бога твого; [Я Господь,] щоб жив брат твій з тобою;","срібла твого не віддавай йому в лихву і хліба твого не віддавай йому для одержання прибутку.","Я Господь, Бог ваш, Який вивів вас із землі Єгипетської, щоб дати вам землю Ханаанську, щоб бути вашим Богом.","Коли зубожіє в тебе брат твій і буде проданий тобі, то не накладай на нього роботи рабської:","він повинен бути у тебе як найманець, як поселенець; до ювілейного року нехай працює у тебе,","а тоді нехай відійде він від тебе, сам і діти його з ним, і повернеться у плем’я своє, і вступить знову у володіння батьків своїх,","тому що вони — Мої раби, яких Я вивів із землі Єгипетської: не слід продавати їх, як продають рабів;","не пануй над ним з жорстокістю і бійся Бога твого.","А щоб раб твій і рабиня твоя були у тебе, то купуйте собі раба і рабиню в народів, які навколо вас;","також і з дітей поселенців, що оселилися у вас, можете купувати, і з племені їх, яке у вас, що народилося у них в землі вашій, і вони можуть бути вашою власністю;","можете передавати їх у спадщину і синам вашим після себе, як маєток; вічно володійте ними, як рабами. А над братами вашими, синами Ізраїлевими, один над одним не володарюйте, не пануйте з жорстокістю.","Якщо прибулець або поселенець твій буде мати достаток, а брат твій перед ним зубожіє і продасться прибульцеві, що оселився у тебе, або кому-небудь із племені прибульця,","то після продажу можна викупити його; хто-небудь із братів його повинен викупити його,","або дядько його, або син дядька його повинен викупити його, або хто-небудь з родичів його, з племені його, повинен викупити його; або якщо буде мати достаток, сам викупиться.","І він повинен розрахуватися з покупцем його, починаючи від того року, коли він продав себе, до року ювілейного, і срібло, за яке він продав себе, слід віддати йому за кількістю років; як тимчасовий найманець він повинен бути в нього;","і якщо ще багато залишається років, то за мірою їх він повинен віддати у викуп за себе срібло, за яке він куплений;","якщо ж мало залишається років до ювілейного року, то він повинен порахувати і за мірою років віддати за себе викуп.","Він повинен бути у нього, як найманець, в усі роки; він не повинен панувати над ним з жорстокістю в очах твоїх.","Якщо ж він не викупиться таким чином, то в ювілейний рік відійде сам і діти його з ним,","тому що сини Ізраїлеві Мої раби; вони Мої раби, яких Я вивів із землі Єгипетської. Я Господь, Бог ваш."],"x":{"3":"1.23.10","4":"4.15.1","9":"2.23.27","10":"4.15.1|31.61.2|2.27.24","13":"3.36.4","14":"2.19.13|69.4.6","17":"2.19.14","18":"2.18.30|10.4.25","19":"25.66.7|31.1.19|36.34.27","21":"4.28.8","23":"3.36.7|10.21.1-3","25":"24.19.25","26":"3.35.12","30":"3.36.4","34":"3.35.2","35":"4.15.8|30.19.1","36":"1.22.25|36.18.8|36.22.12","38":"1.20.2|0.17.7","39":"1.21.2|11.4.1|50.18.25","40":"1.21.2|32.34.14","41":"52.4.18","43":"66.6.9|68.4.1","44":"1.21.4","47":"17.5.8","55":"2.18.2"}},{"v":["Не робіть собі кумирів та ідолів, і стовпів не ставте у себе, і каменів з зображеннями не кладіть у землі вашій, щоб кланятися перед ними, бо Я Господь Бог ваш.","Суботи Мої додержуйте і святилище Моє шануйте: Я Господь.","Якщо ви будете чинити за уставами Моїми і заповіді Мої будете зберігати і виконувати їх,","то Я дам вам дощі у свій час, і земля дасть плоди свої, і дерева польові дадуть плід свій;","і молотьба хліба буде досягати у вас збирання винограду, збирання винограду буде досягати посіву, і будете їсти хліб свій досита, і будете жити на землі [вашій] безпечно;","пошлю мир на землю [вашу], ляжете, і ніхто вас не потурбує, прожену лютих звірів із землі [вашої], і меч не пройде по землі вашій;","і будете проганяти ворогів ваших, і впадуть вони перед вами від меча;","п’ятеро вас проженуть сотню, і сотня з вас прожене десять тисяч, і впадуть вороги ваші перед вами від меча;","зглянусь на вас [і благословлю вас], і плідними зроблю вас, і розмножу вас, і буду твердим у завіті Моїм з вами;","і будете їсти старе минулорічне, і викинете старе заради нового;","і поставлю оселю Мою серед вас, і душа Моя не погордує вами;","і буду ходити серед вас і буду вашим Богом, а ви будете Моїм народом.","Я Господь Бог ваш, Який вивів вас із землі Єгипетської, щоб ви не були там рабами, і знищив кайдани ярма вашого, і повів вас з піднятою головою.","Якщо ж не послухаєте Мене і не будете виконувати всіх заповідей цих,","і якщо знехтуєте Мої постанови, і якщо душа ваша зневажить Мої закони, так що ви не будете виконувати всіх заповідей Моїх, порушивший завіт Мій, —","то і Я зроблю з вами це: пошлю на вас жах, чахлість і гарячку, від яких стомляться очі і змучиться душа, і будете сіяти насіння ваше марно, і вороги ваші з’їдять його;","відверну лице Моє від вас, і впадете перед ворогами вашими, і будуть панувати над вами вороги ваші, і побіжите, коли ніхто не буде гнатися за вами.","Якщо і після всього цього не послухаєте Мене, то Я всемеро збільшу покарання за гріхи ваші,","і зломлю горду завзятість вашу, і небо ваше зроблю, як залізо, і землю вашу, як мідь;","і марно буде виснажуватися сила ваша, і земля ваша не дасть плодів своїх, і дерева землі [вашої] не дадуть плодів своїх.","Якщо ж [після цього] підете проти Мене і не захочете слухати Мене, то Я додам вам ударів усемеро за гріхи ваші:","пошлю на вас звірів польових, які позбавлять вас дітей, знищать худобу вашу і вас зменшать, так що опустіють дороги ваші.","Якщо і після цього не виправитесь і підете проти Мене,","то і Я [в люті] піду проти вас і уражу вас усемеро за гріхи ваші,","і наведу на вас мстивий меч у помсту за завіт; якщо ж ви сховаєтеся в містах ваших, то пошлю на вас моровицю, і віддані будете в руки ворога;","хліб, що підкріплює людину, винищу у вас; десять жінок будуть пекти хліб ваш в одній печі і будуть віддавати хліб ваш на вагу; ви будете їсти і не будете ситі.","Якщо ж і після цього не послухаєте Мене і підете проти Мене,","то і Я в гніві піду проти вас і покараю вас усемеро за гріхи ваші,","і будете їсти плоть синів ваших, і плоть дочок ваших будете їсти;","розорю висоти ваші і зруйную стовпи ваші, і вивергну трупи ваші на уламки ідолів ваших, і гребуватиме душа Моя вами;","міста ваші зроблю пустелею, і спустошу святилища ваші, і не буду чути приємних пахощів [жертв] ваших;","спустошу землю [вашу], так що здивуються щодо неї вороги ваші, що оселилися на ній;","а вас розсію між народами й вийму вслід вам меч, і буде земля ваша порожня і міста ваші зруйновані.","Тоді задовольнить себе земля за суботи свої в усі дні запустіння [свого]; коли ви будете в землі ворогів ваших, тоді буде спочивати земля і задовольнить себе за суботи свої;","в усі дні запустіння [свого] буде вона спочивати, скільки не спочивала в суботи ваші, коли ви жили на ній.","Хто залишиться з вас, пошлю в серця їхні полохливість на землі ворогів їхніх, і шелест листка від вітру пожене їх, і побіжать, як від меча, і впадуть, коли ніхто їх не переслідує,","і спіткнуться один на одного, як від меча, між тим як ніхто не переслідує, і не буде у вас сили протистояти ворогам вашим;","і загинете між народами, і пожере вас земля ворогів ваших;","а хто залишиться з вас, вичахнуть за свої беззаконня в землях ворогів ваших і за беззаконня батьків своїх вичахнуть;","тоді зізнаються вони у беззаконні своїм, і в беззаконні батьків своїх, як вони чинили злочини проти Мене і йшли проти Мене,","за що і Я [у гніві] йшов проти них і ввів їх у землю ворогів їхніх; тоді скориться необрізане серце їх, і тоді потерплять вони за беззаконня свої.","І Я згадаю завіт Мій з Яковом і завіт Мій з Ісааком, і завіт Мій з Авраамом згадаю, і землю згадаю;","тоді, коли земля залишена буде ними і буде задовольняти себе за суботи свої, спустівши від них, і вони будуть терпіти за своє беззаконня, за те, що нехтували закони Мої і душа їх гребувала постановами Моїми,","і тоді, коли вони будуть у землі ворогів їхніх, — Я не знехтую ними і не погребую ними до того, щоб знищити їх, щоб зруйнувати завіт Мій з ними, бо Я Господь, Бог їх;","згадаю для них завіт із предками, яких вивів Я з землі Єгипетської перед очима народів, щоб бути їхнім Богом. Я Господь.","Ось постанови і повеління і закони, які постановив Господь між Собою і між синами Ізраїлевими на горі Синаї, через Мойсея."],"x":{"1":"1.20.4|4.5.8|25.96.7","3":"4.28.1","5":"24.11.19","7":"4.6.19","8":"4.32.30|5.23.10|13.14.9","10":"28.7.14","11":"4.4.7","12":"64.6.16","13":"32.27.2|32.28.2","14":"4.28.15|33.2.17|49.2.2|35.2.10","15":"31.24.5","16":"4.28.21:66|8.2.33","17":"2.17.10|25.33.17","19":"4.28.23","20":"32.8.13|39.1.12","22":"29.11.16:18","24":"9.22.27|25.17.27","25":"36.21.14","26":"25.104.16|36.4.16|50.15.38","28":"4.32.23","29":"11.6.28-29|32.19.9|33.2.20","31":"32.7.14|31.1.13|40.5.21","32":"32.19.8|32.25.9|36.23.25","34":"2.25.2","36":"4.20.3|31.7.4|24.15.21","40":"4.4.30|36.36.31|37.9.16","41":"36.44.7","42":"1.2.24|4.4.29|31.54.10","44":"4.4.29|32.14.9","45":"1.6.5|1.16.6|1.19.5|25.78.8"}},{"v":["І сказав Господь Мойсеєві, говорячи:","оголоси синам Ізраїлевим і скажи їм: якщо хто дає обітницю присвятити душу Господу за оцінкою твоєю,","то оцінка твоя чоловіку від двадцяти років до шістдесяти повинна бути п’ятдесят сиклів срібних, за сиклем священним;","якщо ж це жінка, то оцінка твоя повинна бути тридцять сиклів;","від п’яти років до двадцяти оцінка твоя чоловікові повинна бути двадцять сиклів, а жінці — десять сиклів;","а від місяця до п’яти років оцінка твоя чоловікові повинна бути п’ять сиклів срібла, а жінці оцінка твоя три сиклі срібла;","від шістдесяти років і вище чоловіку оцінка твоя повинна бути п’ятнадцять сиклів срібла, а жінці — десять сиклів.","Якщо ж він бідний і не в силах віддати за оцінкою твоєю, то нехай представлять його священикові, і священик нехай оцінить його: відповідно до достатку того, хто дає обітницю, нехай оцінить його священик.","Якщо ж то буде худоба, яку приносять у жертву Господу, то усе, що дано Господу, повинно бути святим:","не слід вимінювати його і заміняти добре гіршим, або погане добрим; якщо ж стане хто заміняти худобу на худобу, то і вона і заміна її буде святинею.","Якщо ж то буде яка-небудь худоба нечиста, яку не приносять у жертву Господу, то слід представити худобу священикові,","і священик оцінить її, добра вона чи недобра, і як оцінить священик, так і повинно бути;","якщо ж хто хоче викупити її, то нехай додасть п’яту частину до оцінки твоєї.","Якщо хто освячує будинок свій у святиню Господу, то священик повинен оцінити його, добрий він чи недобрий, і як оцінить його священик, так і відбудеться;","якщо ж той, хто посвятив, захоче викупити будинок свій, то нехай додасть п’яту частину срібла оцінки твоєї, і тоді буде його.","Якщо поле зі свого володіння посвятить хто Господу, то оцінка твоя повинна бути за мірою посіву: за посів хомера ячменю п’ятдесят сиклів срібла;","якщо від ювілейного року посвячує хто поле своє, — повинно відбутися за оцінкою твоєю;","якщо ж після ювілею посвячує хто поле своє, то священик повинен розрахувати срібло за кількістю років, що залишилися до ювілейного року, і слід зменшити від оцінки твоєї;","якщо ж захоче викупити поле той, хто посвятив його, то нехай він додасть п’яту частину срібла до оцінки твоєї, і воно залишиться за ним;","якщо ж він не викупить поля, і буде продане поле іншій людині, то вже не можна викупити:","поле те, коли воно в ювілей відійде, буде святинею Господу, ніби поле закляте; священикові дістанеться воно у володіння.","А якщо хто посвятить Господу поле куплене, яке не з полів його володіння,","то священик повинен розрахувати йому міру оцінки до ювілейного року, і повинен він віддати за розрахунком у той самий день, як святиню Господню;","поле ж у ювілейний рік перейде знову до того, у кого куплене, кому належить володіння тієї землі.","Всяка оцінка твоя повинна бути за сиклем священним, двадцять гер повинно бути у сиклі.","Тільки первістків із худоби, які за першістю належать Господу, не повинен ніхто посвячувати: чи віл то, або дрібна худоба, — Господні вони.","Якщо ж худоба нечиста, то слід викупити за оцінкою твоєю і додати до того п’яту частину; якщо не викуплять, то слід продати за оцінкою твоєю.","Тільки все закляте, що під закляттям віддає людина Господу зі своєї власности, — чи людину, чи худобу, чи поле свого володіння, — не продається і не викуповується: усе закляте є велика святиня Господня;","усе закляте, що закляте від людей, не викуповується: воно повинне бути віддане на смерть.","І всяка десятина на землі з насіння землі і з плодів дерева належить Господу: це святиня Господня;","якщо ж хто захоче викупити десятину свою, то нехай додасть до ціни її п’яту частину.","І всяку десятину з великої і дрібної худоби, з усього, що проходить під жезлом десяте, слід присвячувати Господу;","не слід розбирати, добре те чи недобре, і не слід заміняти його; якщо ж хто замінить його, то і саме воно й заміна його буде святинею і не може бути викуплене.","Ось заповіді, які заповів Господь Мойсеєві для синів Ізраїлевих на горі Синаї."],"x":{"2":"3.30.3|4.23.21","16":"36.45.11","24":"2.25.10","25":"1.30.13|3.3.47|3.18.16|36.45.12","26":"1.13.2|3.3.13","27":"2.22.23","28":"3.21.2|5.6.17|8.15.3","29":"5.6.17|6.11.39","30":"1.23.19|4.12.17|75.7.9","34":"2.26.46"}}];
export default C;
